export type PasswordResetLinkRequest = {
    /**
     * The email address of the account.
     */
    email: string;
    /**
     * The console asking, `partner` or `platform`; the link works at that console only. The Agent app signs in with one-time codes and has no password link (`audience_not_allowed`).
     */
    audience: Audience;
};

/**
 * The request body of `POST /v1/auth/password/reset`: the token from the emailed link, the console it is used at and the new password.
 */
export type PasswordReset = {
    /**
     * The token from the link, the last segment of its path.
     */
    token: string;
    /**
     * The console the link is used at: the one it was asked from, `partner` or `platform`.
     */
    audience: Audience;
    /**
     * The new password, 12 to 200 characters and not blank (`password_weak` otherwise).
     */
    new_password: string;
};

/**
 * The request body of `POST /v1/auth/step-up`: exactly one proof of the signed-in person, either `password`, or `authenticator_code`, or `challenge_id` with `code` from `POST /v1/auth/step-up/code`.
 */
export type StepUpRequest = {
    /**
     * Six digits from the authenticator app, while two-step sign-in is on.
     */
    authenticator_code?: string | null;
    /**
     * The `challenge_id` of a code sent by `POST /v1/auth/step-up/code`, together with `code`.
     */
    challenge_id?: string | null;
    /**
     * The six-digit code sent by `POST /v1/auth/step-up/code`, together with `challenge_id`.
     */
    code?: string | null;
    /**
     * The account's password.
     */
    password?: string | null;
};

/**
 * The request body of `POST /v1/auth/step-up/code`: where to send a code that proves the signed-in person, always one of the account's own addresses.
 */
export type StepUpCodeRequest = {
    /**
     * `email` for the account's email address, `phone` for its phone number.
     */
    channel: OtpChannel;
};

/**
 * A pending change of the sign-in email address or phone number, the response of `POST /v1/auth/identifier-change`. The account is unchanged until the code sent to the new address passes at `POST /v1/auth/identifier-change/confirm`.
 */
export type IdentifierChange = {
    /**
     * Whether the email address or the phone number changes.
     */
    channel: OtpChannel;
    /**
     * The new address, waiting for its code.
     */
    identifier: string;
    /**
     * When the code stops working, fifteen minutes after it was sent, as an RFC 3339 timestamp in UTC.
     */
    expires_at: string;
};

/**
 * The request body of `POST /v1/auth/identifier-change`: the new email address or phone number to sign in with.
 */
export type IdentifierChangeRequest = {
    /**
     * `email` to change the email address, `phone` to change the phone number.
     */
    channel: OtpChannel;
    /**
     * The new email address, or the new phone number in E.164 format.
     */
    identifier: string;
};

/**
 * A service token for a background job, the response of `POST /v1/auth/service-tokens`: an access token of audience `service` that names one job, holds no memberships and is refused by every human surface.
 */
export type ServiceToken = {
    /**
     * The token, a JSON Web Token signed with EdDSA, for the `Authorization: Bearer` header of the routes the job may call.
     */
    access_token: string;
    /**
     * Always `Bearer`.
     */
    token_type: 'Bearer';
    /**
     * Seconds until the token expires, at most an hour; mint another from the credential then.
     */
    expires_in: number;
    /**
     * The one job the token may do, its `job` claim.
     */
    job: string;
};

/**
 * The request body of `POST /v1/auth/service-tokens`: the job's bootstrap credential, issued when the job is provisioned and kept in its secret store.
 */
export type ServiceTokenRequest = {
    /**
     * The job's credential. An unknown or revoked credential answers `401` (`authentication_failed`).
     */
    credential: string;
};

/**
 * The optional request body of `POST /v1/auth/sign-out`. Without a body the operation ends the session of the bearer token, or of the refresh cookie a browser sends.
 */
export type SignOutRequest = {
    /**
     * For cookie delivery: the surface whose refresh cookie to read and clear.
     */
    audience?: Audience | null;
    /**
     * `true` ends every session of the user on every surface, not only this one; for a customer session, every customer session of theirs (the customer profile reaches no membership).
     */
    everywhere?: boolean;
    /**
     * For body delivery: the refresh token, so an app whose access token expired can still end its session.
     */
    refresh_token?: string | null;
};

/**
 * What the account says about its own credentials, for the account page of every console.
 */
export type MeAccount = {
    /**
     * Whether a password is set; a user without one signs in with one-time codes.
     */
    password_set: boolean;
    /**
     * Whether two-step sign-in is on.
     */
    two_step_enabled: boolean;
    /**
     * `true` while this session reaches the two-step set-up only: platform staff set up a second factor before Mission Control opens.
     */
    two_step_setup_required: boolean;
    /**
     * When the password was last set, as an RFC 3339 timestamp in UTC; `null` without a password.
     */
    password_changed_at?: string | null;
    /**
     * A new email address waiting for its code while a change is pending; `null` otherwise.
     */
    pending_email?: string | null;
    /**
     * A new phone number waiting for its code while a change is pending; `null` otherwise.
     */
    pending_phone?: string | null;
    /**
     * How many recovery codes are left while two-step sign-in is on; `null` while it is off.
     */
    recovery_codes_remaining?: number | null;
};

/**
 * One of the user's agent memberships, as `GET /v1/me` lists them on the Agent app: the Service of a partner the person executes tasks for.
 */
export type MeAgentMembership = {
    /**
     * The agent membership.
     */
    agent_id: string;
    /**
     * The partner whose Service it is.
     */
    partner_id: string;
    /**
     * The kind of the Service, for example `delivery`.
     */
    service_kind: ServiceKind;
    /**
     * The name the agent is shown under.
     */
    display_name: string;
    /**
     * The partner's name; `null` when the partner no longer exists.
     */
    partner_name?: string | null;
    /**
     * The Service; `null` for a membership that predates Services.
     */
    service_id?: string | null;
};

/**
 * The user's platform membership as `GET /v1/me` shows it on Mission Control, with every grant and the permissions it carries.
 */
export type MePlatform = {
    /**
     * The platform membership.
     */
    membership_id: string;
    /**
     * Every platform grant, each with its role and the permissions of that role.
     */
    grants: Array<AccessGrant>;
};

/**
 * In `GET /v1/me` under a view-as (impersonation) token: who views, which one Partner, whether changes are allowed and until when. The token reaches that Partner and nothing else of the owner's.
 */
export type MeImpersonation = {
    /**
     * The impersonation session.
     */
    impersonation_id: string;
    /**
     * The one Partner the owner's consent covers.
     */
    partner_id: string;
    /**
     * The platform member viewing.
     */
    member_user_id: string;
    /**
     * Their name, when they gave one.
     */
    member_display_name: string | null;
    /**
     * Whether the owner allowed changes; viewing only otherwise.
     */
    writes_allowed: boolean;
    /**
     * When the view-as token stops working.
     */
    expires_at: string;
};

/**
 * One of the user's partner memberships as `GET /v1/me` lists them on the Partner console: the membership, the partner it is in, and every grant with its scope and the permissions held there, never merged. `role` is the most senior default role held, or `custom`.
 */
export type MeMembership = {
    /**
     * Unique identifier of the membership.
     */
    id: string;
    /**
     * The partner.
     */
    partner_id: string;
    /**
     * The member, the signed-in user.
     */
    user: User;
    /**
     * The most senior default role held (`owner`, `manager`, `dispatcher`, `kitchen`, `staff`), or `custom` for a role the partner defined or access held only at chosen Locations or Services.
     */
    role: MembershipRole;
    /**
     * When the membership was created, as an RFC 3339 timestamp in UTC.
     */
    created_at: string;
    /**
     * The partner's name.
     */
    partner_name: string;
    /**
     * `organisation` or `individual`.
     */
    partner_kind: PartnerKind;
    /**
     * `pending`, `active` or `suspended`.
     */
    partner_status: PartnerStatus;
    /**
     * Whether a grant carries `partner:access`; a membership without it opens nothing of the partner in the console.
     */
    console_access: boolean;
    /**
     * Every grant, each with its scope and the permissions held there.
     */
    grants: Array<AccessGrant>;
    /**
     * The Service, for an agent membership; `null` for a partner's staff.
     */
    service_id?: string | null;
};

/**
 * Whether the partner is an `organisation` (a company, a shop, a restaurant
 * chain) or an `individual` (a sole trader, a single person providing fleet
 * capacity). The kind is set when the partner is created and does not
 * change. Clients must tolerate values they do not know, because a new kind
 * is an additive change.
 *
 */
export type PartnerKind = 'organisation' | 'individual';

/**
 * The partner's standing on the platform. A partner is `pending` from its
 * creation until the platform activates it, `active` while it operates,
 * `suspended` when the platform has stopped it (with a reason), and
 * `archived` once retired, when nothing new may refer to it. Only the
 * platform realm changes the status, along the lifecycle's transitions:
 * pending to active or archived, active to suspended or archived, suspended
 * to active or archived. Clients must tolerate values they do not know,
 * because a new status is an additive change.
 *
 */
export type PartnerStatus = 'pending' | 'active' | 'suspended' | 'archived';

/**
 * A partner, the supply-side tenant: an organisation or an individual that
 * sells products, sells services or provides fleet capacity. Everything in
 * the API belongs to exactly one partner. Users work in a partner through
 * memberships; the user who creates a partner becomes its first owner.
 *
 */
export type Partner = {
    /**
     * Unique identifier of the partner.
     */
    id: string;
    /**
     * Whether the partner is an organisation or an individual.
     */
    kind: PartnerKind;
    /**
     * The name the partner operates under.
     */
    name: string;
    /**
     * The registered legal name, or `null` when none was given.
     */
    legal_name: string | null;
    /**
     * The partner's standing on the platform.
     */
    status: PartnerStatus;
    /**
     * The email address the platform reaches the partner at, or `null`.
     */
    contact_email: string | null;
    /**
     * The phone number the platform reaches the partner at, in E.164 format, or `null`.
     */
    contact_phone: string | null;
    /**
     * When the partner was created, as an RFC 3339 timestamp in UTC.
     */
    created_at: string;
    /**
     * When the partner was last changed, as an RFC 3339 timestamp in UTC; equal to `created_at` until the first change.
     */
    updated_at: string;
    /**
     * The version, raised by one on every change. Reads return it as the `ETag` (`"v<version>"`); send it in `If-Match` on a write to be refused with `412` when the partner moved.
     */
    version: number;
    /**
     * The user who created the partner, or `null` for seeded partners.
     */
    created_by: string | null;
    /**
     * The user who last changed the partner, or `null` until it is changed through the API.
     */
    updated_by: string | null;
    /**
     * The country the Partner is registered in (ISO 3166-1 alpha-2); India at launch.
     */
    country: string;
    /**
     * Whether platform staff recorded the organisation as not registered for GST, so no GST registration is asked of it.
     */
    gst_unregistered: boolean;
    /**
     * The people to reach about what, with their consent per channel.
     */
    contacts: Array<Contact>;
    /**
     * The Partner's banner, an asset of the `partner_banner` purpose; twice as wide as tall.
     */
    banner_asset_id?: string | null;
    /**
     * What the Partner does, in its own words.
     */
    description?: string | null;
    /**
     * The GSTIN, for an organisation registered for GST.
     */
    gstin?: string | null;
    /**
     * The moment of first activation, the launch date; `null` until activated.
     */
    launched_at?: string | null;
    /**
     * The Partner's logo, an asset of the `partner_logo` purpose; square.
     */
    logo_asset_id?: string | null;
    /**
     * The Permanent Account Number: the person's for an individual, the entity's for an organisation.
     */
    pan?: string | null;
    /**
     * The plan, which decides the kinds of Service it may run: Pro while it is set up and for its thirty-day trial from activation.
     */
    plan?: Plan;
    /**
     * The registered address, in the Partner's country.
     */
    registered_address?: Address | null;
    /**
     * The company or LLP registration number, for an organisation that has one.
     */
    registration_number?: string | null;
    /**
     * When the status last changed; `null` for a Partner whose status never changed.
     */
    status_changed_at?: string | null;
    /**
     * Who last changed the status; `null` when never changed or changed by the platform itself.
     */
    status_changed_by?: string | null;
    /**
     * Why the Partner is in its status, shown to its members while it is suspended.
     */
    status_reason?: string | null;
    /**
     * Where the Partner stands, on directory reads and on a single read: whether it can trade, its Locations, members, documents and payout account; absent on writes.
     */
    standing?: PartnerStandingSummary | null;
};

/**
 * The request body of `POST /v1/partners`. The partner starts with the
 * status `pending`. Without `owner` the caller becomes the partner's first
 * owner; Mission Control onboards a partner for somebody else by naming
 * the `owner`, and may withhold permissions from the partner's
 * entitlements from the start.
 *
 */
export type PartnerCreate = {
    /**
     * Whether the partner is an organisation or an individual; it cannot be changed later.
     */
    kind: PartnerKind;
    /**
     * The name the partner operates under.
     */
    name: string;
    /**
     * The registered legal name. Omit it, or send `null`, when there is none to give.
     */
    legal_name?: string | null;
    /**
     * The email address the platform may reach the partner at. Omit it, or send `null`, to leave it unset.
     */
    contact_email?: string | null;
    /**
     * The phone number the platform may reach the partner at, in E.164 format. Omit it, or send `null`, to leave it unset.
     */
    contact_phone?: string | null;
    /**
     * The people to reach, with their consent per channel.
     */
    contacts?: Array<Contact>;
    /**
     * What the Partner does, in its own words.
     */
    description?: string | null;
    /**
     * The GSTIN, for an organisation registered for GST; it embeds the PAN.
     */
    gstin?: string | null;
    /**
     * The administrator, for Mission Control's onboarding on the Partner's behalf (platform staff holding `partner:write` and `staff:write`, and required of them): an existing user is attached as the Partner's owner and told, a new person is invited by email. Omitted from the Partner console, where the caller becomes the owner.
     */
    owner?: PartnerOwner | null;
    /**
     * The Permanent Account Number.
     */
    pan?: string | null;
    /**
     * The registered address, in India.
     */
    registered_address?: Address | null;
    /**
     * The company or LLP registration number, for an organisation that has one.
     */
    registration_number?: string | null;
    /**
     * Permissions to withhold from the partner's entitlements, for platform staff onboarding a partner; never `partner:access` (`partner_cannot_sign_in`).
     */
    withheld_permissions?: Array<string>;
};

/**
 * The request body of `PATCH /v1/partners/{partner_id}`. Only the members
 * present are changed; `null` clears a member that may be `null` in the
 * resource. Changing the profile and the legal identity needs
 * `partner:profile:write` (platform staff `partner:write`); `status`,
 * `kind` and `gst_unregistered` may only be changed by the platform
 * realm.
 *
 */
export type PartnerUpdate = {
    /**
     * The new name the partner operates under.
     */
    name?: string;
    /**
     * The new registered legal name, or `null` to clear it.
     */
    legal_name?: string | null;
    /**
     * The new contact email address, or `null` to clear it.
     */
    contact_email?: string | null;
    /**
     * The new contact phone number in E.164 format, or `null` to clear it.
     */
    contact_phone?: string | null;
    /**
     * The new status. Platform realm only; any other caller receives `403` (`forbidden`).
     */
    status?: PartnerStatus;
    /**
     * Why the status is changed, kept in the audit log with the entry for the change. Sent with `status`.
     */
    reason?: string;
    /**
     * The contacts, replaced as a whole.
     */
    contacts?: Array<Contact> | null;
    /**
     * New description, or `null` to clear.
     */
    description?: string | null;
    /**
     * `true` records the organisation as not registered for GST, so no GST registration is asked of it; platform realm only, with a `reason`.
     */
    gst_unregistered?: boolean | null;
    /**
     * New GSTIN, or `null` to clear.
     */
    gstin?: string | null;
    /**
     * New kind; platform realm only, with a `reason`. Locations, members, documents and settings are kept.
     */
    kind?: PartnerKind | null;
    /**
     * New PAN, or `null` to clear.
     */
    pan?: string | null;
    /**
     * New registered address, or `null` to clear.
     */
    registered_address?: Address | null;
    /**
     * New registration number, or `null` to clear.
     */
    registration_number?: string | null;
};

/**
 * A page of partners, the response of `GET /v1/partners`.
 */
export type PartnerList = {
    /**
     * The partners on this page, newest first.
     */
    items: Array<Partner>;
    /**
     * An opaque cursor to pass as `cursor` for the next page, or `null` when this is the last page.
     */
    next_cursor: string | null;
    /**
     * Facet counts, present when `facets` was asked for.
     */
    facets?: Array<Facet>;
};

/**
 * Where a location is in its lifecycle, the one partners share: `pending`
 * from its opening until it goes live, `active` while it operates,
 * `suspended` while stopped, `archived` once retired. Moves: pending to
 * active or archived, active to suspended or archived, suspended to active
 * or archived, archived to pending (platform staff only). `inactive` is the
 * step 1 name of `suspended`, still accepted on input and never returned.
 * Clients must tolerate values they do not know, because a new status is an
 * additive change.
 *
 */
export type LocationStatus = 'active' | 'inactive' | 'pending' | 'suspended' | 'archived';

/**
 * A physical place that belongs to a partner: a store, a restaurant, a dark
 * store, a warehouse or a service base. Pickups happen at locations and the
 * partner's local operations are anchored to them. Coordinates are WGS 84.
 *
 */
export type Location = {
    /**
     * Unique identifier of the location.
     */
    id: string;
    /**
     * The partner the location belongs to.
     */
    partner_id: string;
    /**
     * The name the location is known by within the partner.
     */
    name: string;
    /**
     * The postal address.
     */
    address: Address;
    /**
     * Latitude in decimal degrees (WGS 84).
     */
    lat: number;
    /**
     * Longitude in decimal degrees (WGS 84).
     */
    lng: number;
    /**
     * The IANA time zone the location operates in, for example `Asia/Kolkata`. Opening hours and local times are interpreted in it.
     */
    time_zone: string;
    /**
     * The phone number of the location in E.164 format, or `null`.
     */
    phone: string | null;
    /**
     * Whether the location takes part in operations.
     */
    status: LocationStatus;
    /**
     * When the location was created, as an RFC 3339 timestamp in UTC.
     */
    created_at: string;
    /**
     * When the location was last changed, as an RFC 3339 timestamp in UTC; equal to `created_at` until the first change.
     */
    updated_at: string;
    /**
     * The version, raised by one on every change. Reads return it as the `ETag` (`"v<version>"`); send it in `If-Match` on a write to be refused with `412` when the location moved.
     */
    version: number;
    /**
     * The user who created the location, or `null` for seeded locations.
     */
    created_by: string | null;
    /**
     * The user who last changed the location, or `null` until it is changed through the API.
     */
    updated_by: string | null;
    /**
     * The service area the location's pin resolves to, set when the location is created or its pin moves; `null` for locations placed before service areas existed. See `GET /v1/service-areas/resolve`.
     */
    service_area_id: string | null;
    /**
     * Whether the pin lies inside the zone's fence; outside is a warning, not a refusal.
     */
    pin_in_zone: boolean;
    /**
     * The people to reach at the Location, with their consent per channel.
     */
    contacts: Array<Contact>;
    /**
     * The Verticals it trades in, each offered in its zone.
     */
    vertical_ids: Array<string>;
    /**
     * Its categories within those Verticals.
     */
    category_ids: Array<string>;
    /**
     * How orders leave it (a store's).
     */
    fulfilment: Fulfilment;
    /**
     * How it takes orders (a store's).
     */
    order_settings: OrderSettings;
    /**
     * How it appears on the storefront (a store's).
     */
    listing: Listing;
    /**
     * Typed extra fields the types of its Services declare (a food store's FSSAI licence number), checked against the reference data's field catalogue.
     */
    fields: {
        [key: string]: unknown;
    };
    /**
     * Its banner, a `location_banner` asset twice as wide as tall.
     */
    banner_asset_id?: string | null;
    /**
     * What keeps it from going live, the same blockers an activation is refused with; on reads.
     */
    blockers?: Array<Blocker> | null;
    /**
     * The currency of its zone's country.
     */
    currency?: string | null;
    /**
     * When it was deleted, for a Location in the bin.
     */
    deleted_at?: string | null;
    /**
     * What the Location is, in its own words.
     */
    description?: string | null;
    /**
     * Set when somebody asked it to go live while its Partner was pending: the Partner's activation brings it live with it.
     */
    go_live_requested_at?: string | null;
    /**
     * What it is doing now, at one instant; on reads.
     */
    live?: LocationLive | null;
    /**
     * Its tile on the storefront, a square `location_logo` asset.
     */
    logo_asset_id?: string | null;
    /**
     * The pause in force or last set; it ends by itself at `until`.
     */
    pause?: Pause | null;
    /**
     * A store when a product-sales Service is on there, else a branch; on reads.
     */
    reads_as?: ReadsAs | null;
    /**
     * The Services switched on here and whether each trades here now, from the registry; on reads.
     */
    services?: Array<LocationService> | null;
    /**
     * When the status last changed.
     */
    status_changed_at?: string | null;
    /**
     * Who last changed the status.
     */
    status_changed_by?: string | null;
    /**
     * Why it is in that status, for a suspension.
     */
    status_reason?: string | null;
    /**
     * Softer gaps shown without stopping anybody (a pin outside the zone, nobody to call); on reads.
     */
    warnings?: Array<Blocker> | null;
    /**
     * When it first went live.
     */
    went_live_at?: string | null;
};

/**
 * The request body of `POST /v1/partners/{partner_id}/locations`. A new
 * location is `active`. Coordinates are required because the platform does
 * not geocode addresses; the pin must fall inside a fenced service area or
 * within 10 km of one, else the request is refused with `422`
 * (`unprocessable`) naming `/lat` and `/lng`.
 *
 */
export type LocationCreate = {
    /**
     * The name the location is known by within the partner.
     */
    name: string;
    /**
     * The postal address.
     */
    address: Address;
    /**
     * Latitude in decimal degrees (WGS 84).
     */
    lat: number;
    /**
     * Longitude in decimal degrees (WGS 84).
     */
    lng: number;
    /**
     * The IANA time zone the location operates in. `Asia/Kolkata` when omitted.
     */
    time_zone?: string;
    /**
     * The phone number of the location in E.164 format. Omit it, or send `null`, to leave it unset.
     */
    phone?: string | null;
    /**
     * Its categories within those Verticals.
     */
    category_ids?: Array<string>;
    /**
     * The people to reach there, with their consent per channel.
     */
    contacts?: Array<Contact>;
    /**
     * What the Location is, in its own words.
     */
    description?: string | null;
    /**
     * The Verticals it trades in, each offered in the zone its pin resolves to.
     */
    vertical_ids?: Array<string>;
};

/**
 * The request body of `PATCH /v1/partners/{partner_id}/locations/{location_id}`.
 * Only the members present are changed; `null` clears a member that may be
 * `null` in the resource. `address` is replaced as a whole when present.
 *
 */
export type LocationUpdate = {
    /**
     * The new name.
     */
    name?: string;
    /**
     * The new postal address, replacing the previous one as a whole.
     */
    address?: Address;
    /**
     * The new latitude in decimal degrees (WGS 84).
     */
    lat?: number;
    /**
     * The new longitude in decimal degrees (WGS 84).
     */
    lng?: number;
    /**
     * The new IANA time zone.
     */
    time_zone?: string;
    /**
     * The new phone number in E.164 format, or `null` to clear it.
     */
    phone?: string | null;
    /**
     * The new status.
     */
    status?: LocationStatus;
    /**
     * The categories, replaced as a whole.
     */
    category_ids?: Array<string> | null;
    /**
     * The contacts, replaced as a whole.
     */
    contacts?: Array<Contact> | null;
    /**
     * New description, or `null` to clear.
     */
    description?: string | null;
    /**
     * The typed extra fields the types of the Location's Services declare (a food store's `fssai_licence_number`), replaced as a whole; a value of the wrong shape or a field no type declares is refused, a required one left out blocks going live.
     */
    fields?: {
        [key: string]: unknown;
    } | null;
    /**
     * The reason for a status change, kept in the audit log.
     */
    reason?: string | null;
    /**
     * The Verticals, replaced as a whole; each offered in the Location's zone.
     */
    vertical_ids?: Array<string> | null;
};

/**
 * A list of a partner's locations, the response of `GET /v1/partners/{partner_id}/locations`.
 */
export type LocationList = {
    /**
     * The partner's locations, oldest first. The list is not paginated.
     */
    items: Array<Location>;
};

/**
 * The role a member holds in a partner, as a single label. `owner` may do
 * everything the partner is entitled to, including managing members and
 * roles; `manager`, `dispatcher`, `kitchen` and `staff` are the default
 * roles every partner receives and may tune; `custom` stands for a role
 * the partner defined, or for access held only at chosen Locations or
 * Services. When a member holds several roles the label is the most senior
 * one. What a member may do is decided by their grants and the permissions
 * in them, listed under the `Access` tag, never by this label; it is kept so
 * that every operation that answered with a role still does. In a request
 * (an invitation), `custom` is refused: name the role with `role_id`.
 * Clients must tolerate values they do not know, because a new role is an
 * additive change.
 *
 */
export type MembershipRole = 'owner' | 'manager' | 'dispatcher' | 'kitchen' | 'staff' | 'custom';

/**
 * A user's membership in a partner, with the role that decides what they may
 * do there. A user holds at most one membership per partner. A membership is
 * not an agent record: a member works in the partner's account, an agent is
 * attached to one of the partner's services to execute tasks.
 *
 */
export type Membership = {
    /**
     * Unique identifier of the membership.
     */
    id: string;
    /**
     * The partner the user is a member of.
     */
    partner_id: string;
    /**
     * The member.
     */
    user: User;
    /**
     * The member's role in the partner.
     */
    role: MembershipRole;
    /**
     * When the membership was created, as an RFC 3339 timestamp in UTC.
     */
    created_at: string;
};

/**
 * A list of a partner's members, the response of `GET /v1/partners/{partner_id}/memberships`.
 */
export type MembershipList = {
    /**
     * The partner's memberships, oldest first. The list is not paginated.
     */
    items: Array<Membership>;
};

/**
 * The state of an invitation. It is `pending` until it is `accepted` by the
 * invited person, `revoked` by the partner or `expired` by passing
 * `expires_at`. Clients must tolerate values they do not know, because a
 * new status is an additive change.
 *
 */
export type InvitationStatus = 'pending' | 'accepted' | 'expired' | 'revoked';

/**
 * An invitation to join a partner, or the platform, with a role, sent by
 * email. The invited person accepts it with the token from the email
 * through `POST /v1/invitations/{token}/accept`; the token itself is never
 * returned by the API. The invitation is `pending` until it is accepted,
 * revoked or past `expires_at`.
 *
 */
export type Invitation = {
    /**
     * Unique identifier of the invitation.
     */
    id: string;
    /**
     * The partner the invitation is for; the platform organisation for an invitation into the platform.
     */
    partner_id: string;
    /**
     * The email address the invitation was sent to.
     */
    email: string;
    /**
     * The default role the membership will have once the invitation is accepted, or `custom` for a role the partner defined.
     */
    role: MembershipRole;
    /**
     * The state of the invitation.
     */
    status: InvitationStatus;
    /**
     * When the invitation stops being acceptable, as an RFC 3339 timestamp in UTC.
     */
    expires_at: string;
    /**
     * When the invitation was created, as an RFC 3339 timestamp in UTC.
     */
    created_at: string;
    /**
     * The role to grant on acceptance; `null` for an invitation into the platform, whose roles are granted afterwards.
     */
    role_id?: string | null;
    /**
     * The Locations the role is limited to; empty for the whole partner.
     */
    location_ids: Array<string>;
    /**
     * The Services the role is limited to; empty for the whole partner.
     */
    service_ids: Array<string>;
    /**
     * The name the invitee will be shown under, when one was given.
     */
    display_name?: string | null;
};

/**
 * The request body of `POST /v1/partners/{partner_id}/invitations`: who to
 * invite, the role to grant on acceptance and where it applies. Name the
 * role with `role_id` (any role of the partner) or, as in step 1, with
 * `role` (a default role by name); one of the two is required
 * (`validation_failed` on `/role_id` otherwise). The owner role covers the
 * whole partner (`invalid_scope` with Locations or Services). Nobody hands
 * out a role holding more than they hold (`permission_escalation`).
 *
 */
export type InvitationCreate = {
    /**
     * The email address to send the invitation to. It becomes the email address of the user if the invitation creates one.
     */
    email: string;
    /**
     * A default role by name (`custom` is refused); `role_id` wins when both are sent.
     */
    role?: MembershipRole;
    /**
     * The role to grant, any role of the partner.
     */
    role_id?: string | null;
    /**
     * The Locations the role is limited to; empty or absent for the whole partner.
     */
    location_ids?: Array<string>;
    /**
     * The Services the role is limited to; empty or absent for the whole partner.
     */
    service_ids?: Array<string>;
    /**
     * The name the invitee will be shown under in the partner.
     */
    display_name?: string | null;
};

/**
 * A list of invitations, the response of `GET /v1/partners/{partner_id}/invitations` and `GET /v1/platform/invitations`.
 */
export type InvitationList = {
    /**
     * The partner's invitations in every status, newest first. The list is not paginated.
     */
    items: Array<Invitation>;
};

/**
 * The request body of `POST /v1/invitations/{token}/accept`. `delivery`,
 * required, says how the new session's refresh token travels.
 * `display_name` is used only when the call creates the user and
 * `password` only when the user has no password yet; a person who already
 * has an account keeps their name and password.
 *
 */
export type InvitationAcceptRequest = {
    /**
     * The name the new user is shown under.
     */
    display_name?: string;
    /**
     * A password for a user who has none yet, 12 to 200 characters, so that they can also sign in with `POST /v1/auth/password/sign-in`. Without it the user signs in with one-time codes until they set one.
     */
    password?: string;
    /**
     * How the refresh token of the new session travels, required (`validation_failed` with `delivery_required` on `/delivery`): `cookie` (browsers) or `body` (apps). The session is for the surface the invitation was for: Mission Control for an invitation into the platform (with no role while it waits for approval), the Partner console otherwise.
     */
    delivery: Delivery;
};

/**
 * The response of `POST /v1/invitations/{token}/accept` when the invitee's two-step sign-in is on: the membership exists, and the session waits for an authenticator or recovery code at `POST /v1/auth/two-step/verify`.
 */
export type InvitationSecondStep = {
    /**
     * The second step the session waits for.
     */
    second_step: TwoStepChallenge;
    /**
     * The new membership.
     */
    membership: Membership;
};

/**
 * The response of `POST /v1/invitations/{token}/accept`: the session of the
 * person who accepted, signed in the same way as after a one-time code, and
 * the membership the invitation turned into. When the person has two-step
 * sign-in on, the answer is an `InvitationSecondStep` with `202` instead.
 *
 */
export type InvitationAccepted = {
    /**
     * The session for the user who accepted; the refresh token is delivered as for the sign-in operations.
     */
    token: TokenResponse;
    /**
     * The new membership in the partner that sent the invitation.
     */
    membership: Membership;
};

/**
 * The kind of service a partner runs: `product_sales` sells products from a
 * catalog for delivery, pickup or dine-in; `field_service` performs services
 * at the customer's place; `delivery` moves goods with the partner's own
 * agents. A partner may run several kinds, each configured as a `Service`,
 * and every agent is attached to one of them. Clients must tolerate values
 * they do not know, because a new kind is an additive change.
 *
 */
export type ServiceKind = 'product_sales' | 'field_service' | 'delivery';

/**
 * Whether a partner's service is in operation. An `enabled` service trades
 * where it is switched on; an `awaiting_documents` service is enabled but
 * waits for the documents its kind needs to be approved, configurable and
 * not trading (the platform sets it, a client never sends it); a `disabled`
 * service keeps its configuration but takes no part in operations. Clients
 * must tolerate values they do not know, because a new status is an
 * additive change.
 *
 */
export type ServiceStatus = 'enabled' | 'disabled' | 'awaiting_documents';

/**
 * A service a partner runs: a line of business of one kind (product sales,
 * field service or delivery), with its name, status and configuration, the
 * locations it is switched on at, and whether it trades there now with what
 * stops it. A partner may run several services of one kind. Registered with
 * `POST /v1/partners/{partner_id}/services` and changed with `PATCH`; the
 * step 1 `PUT /v1/partners/{partner_id}/services/{kind}` keeps working on the
 * partner's first service of the kind.
 *
 */
export type Service = {
    /**
     * Unique identifier of the service.
     */
    id: string;
    /**
     * The partner that runs the service.
     */
    partner_id: string;
    /**
     * The kind of service.
     */
    kind: ServiceKind;
    /**
     * Whether the service is in operation.
     */
    status: ServiceStatus;
    /**
     * Settings specific to the kind of service, as last put. The keys of each kind are documented when that kind's features are released; an empty object when nothing is configured.
     */
    config: {
        [key: string]: unknown;
    };
    /**
     * When the service was first put, as an RFC 3339 timestamp in UTC.
     */
    created_at: string;
    /**
     * When the service was last put, as an RFC 3339 timestamp in UTC; equal to `created_at` until the first change.
     */
    updated_at: string;
    /**
     * Its name, defaulting to its kind.
     */
    name: string;
    /**
     * `true` when it is switched on at every Location of the Partner, present and future.
     */
    everywhere: boolean;
    /**
     * The Locations it is switched on at (every open Location when `everywhere`).
     */
    location_ids: Array<string>;
    /**
     * The documents it waits for, while `awaiting_documents`.
     */
    awaiting: Array<DocumentKind>;
    /**
     * `true` when it trades somewhere now: enabled, in the plan, the Partner active, switched on at a Location, and with agents for an agent-based kind.
     */
    trading: boolean;
    /**
     * What stops it trading, each with its code: `service_disabled`, `document_missing`, `document_pending`, `document_rejected`, `document_expired`, `not_in_plan`, `partner_not_active`, `switched_on_nowhere`, `no_agents`.
     */
    blockers: Array<Blocker>;
    /**
     * The version, raised by one on every change.
     */
    version: number;
    /**
     * The agents holding a membership in it, for delivery and field Services; `null` for product sales or when the fleet cannot say.
     */
    agents?: number | null;
    /**
     * Who registered it; `null` for the step 1 rows and the seed.
     */
    created_by?: string | null;
    /**
     * The current pricing version, for a delivery Service that has one.
     */
    pricing_version?: number | null;
    /**
     * Why it is in its status, when platform staff or a plan change set it.
     */
    status_reason?: string | null;
    /**
     * Who last changed it.
     */
    updated_by?: string | null;
};

/**
 * The request body of `PUT /v1/partners/{partner_id}/services/{kind}`.
 * `config` replaces the stored configuration as a whole when present; when
 * it is omitted the existing configuration is kept, or an empty object is
 * stored for a new service. `status` is `enabled` or `disabled`;
 * `awaiting_documents` is the platform's to set and is refused.
 *
 */
export type ServiceUpsert = {
    /**
     * Whether the service is in operation.
     */
    status: ServiceStatus;
    /**
     * The settings for the kind of service, replacing the stored ones as a whole. The keys of each kind are documented when that kind's features are released.
     */
    config?: {
        [key: string]: unknown;
    };
    /**
     * A new name; kept when omitted.
     */
    name?: string | null;
    /**
     * Why; required of platform staff acting for the Partner.
     */
    reason?: string | null;
};

/**
 * The registry of a partner, the response of `GET /v1/partners/{partner_id}/services`: its services, where every kind stands for it, and its plan.
 */
export type ServiceList = {
    /**
     * The partner's services, oldest first, in any status; several of a kind when the partner runs several. The list is not paginated.
     */
    items: Array<Service>;
    /**
     * Every kind and where it stands for the Partner: enabled, awaiting documents, disabled, available, or not in the plan with the plan that includes it.
     */
    kinds: Array<KindAvailability>;
    /**
     * The plan in force, with the kinds it includes.
     */
    plan: PlanOffer;
};

/**
 * What keeps a Partner or a Location from going live, the `Blocker` schema: a stable code from `activation_blocked`'s field-level codes, a sentence a screen may show verbatim, and where in the record it points.
 */
export type Blocker = {
    /**
     * The stable code, for example `document_missing`.
     */
    code: string;
    /**
     * A sentence saying what stands in the way.
     */
    message: string;
    /**
     * A JSON Pointer into the record, for example `/documents/pan`.
     */
    pointer: string;
};

/**
 * What activating a Partner needs, the `PartnerActivation` schema: the setup checklist the consoles show before anybody tries, the same blockers an attempt would be refused with.
 */
export type PartnerActivation = {
    /**
     * The Partner's status.
     */
    status: PartnerStatus;
    /**
     * `true` when nothing blocks activation; for a Partner that is not pending it says whether an activation would pass.
     */
    ready: boolean;
    /**
     * What stands in the way, each with its code; empty when ready.
     */
    blockers: Array<Blocker>;
};

/**
 * The administrator Mission Control names when it onboards a Partner, its first owner: an existing user is attached and told, a new person is invited by email.
 */
export type PartnerOwner = {
    /**
     * The administrator's email address: an existing user's is attached at once and told there, a new person's invitation goes there.
     */
    email: string;
    /**
     * The administrator's name.
     */
    display_name: string;
};

/**
 * A person to reach about something, the `Contact` schema.
 */
export type Contact = {
    /**
     * What the contact is for.
     */
    purpose: ContactPurpose;
    /**
     * What they agreed to be reached on.
     */
    consent?: ContactConsent;
    /**
     * Their email address.
     */
    email?: string | null;
    /**
     * The person's name.
     */
    name?: string | null;
    /**
     * Their phone number in E.164; a number without a calling code is taken as Indian.
     */
    phone?: string | null;
    /**
     * Their role.
     */
    role?: string | null;
};

/**
 * What a contact agreed to be reached on, the `ContactConsent` schema. Consent is per person and per channel, and never inferred from a number or an address being present.
 */
export type ContactConsent = {
    /**
     * Agreed to email.
     */
    email?: boolean;
    /**
     * Agreed to SMS.
     */
    sms?: boolean;
    /**
     * Agreed to WhatsApp.
     */
    whatsapp?: boolean;
};

/**
 * What a contact is for. A notice looks for its purpose, then operations, then anybody.
 */
export type ContactPurpose = 'operations' | 'finance' | 'escalation' | 'legal';

/**
 * The Partner console's view of its registration and standing, the `PartnerStanding` schema.
 */
export type PartnerStanding = {
    /**
     * The Partner.
     */
    partner_id: string;
    /**
     * Its lifecycle status.
     */
    status: PartnerStatus;
    /**
     * What activation needs, with every blocker.
     */
    activation: PartnerActivation;
    /**
     * Every document the Partner must have on file and where each stands: its review, its expiry, and what it does to trading.
     */
    requirements: Array<DocumentRequirement>;
    /**
     * Whether the next payout may go out now: the account verified and any hold over.
     */
    payouts_may_go: boolean;
    /**
     * The permissions withheld from the Partner's entitlement envelope.
     */
    withheld_permissions: Array<string>;
    /**
     * The directory summary.
     */
    summary: PartnerStandingSummary;
    /**
     * The launch date.
     */
    launched_at?: string | null;
    /**
     * The payout account, masked; `null` until stated.
     */
    payout_account?: PayoutAccount | null;
    /**
     * When the status last changed.
     */
    status_changed_at?: string | null;
    /**
     * Why it is in that status, shown while it is suspended.
     */
    status_reason?: string | null;
};

/**
 * What the directory row carries beside a Partner, the `PartnerStandingSummary` schema.
 */
export type PartnerStandingSummary = {
    /**
     * Whether the Partner can trade now: active, and no document has stopped every Location.
     */
    can_trade: boolean;
    /**
     * Its Locations.
     */
    locations_total: number;
    /**
     * Its Locations that are live.
     */
    locations_live: number;
    /**
     * Members who can sign in.
     */
    members_can_sign_in: number;
    /**
     * `true` when nobody can sign in to the Partner, which platform staff should notice.
     */
    nobody_can_sign_in: boolean;
    /**
     * Required documents approved.
     */
    documents_approved: number;
    /**
     * Required documents awaiting review.
     */
    documents_pending: number;
    /**
     * Required documents missing, rejected or expired.
     */
    documents_missing: number;
    /**
     * Where the payout account stands.
     */
    payout_account: PayoutStanding;
    /**
     * The kinds of Service it runs: those with a Service enabled or awaiting documents.
     */
    runs: Array<ServiceKind>;
};

/**
 * Where a Partner's payout account stands, for the directory.
 */
export type PayoutStanding = 'none' | 'unverified' | 'verified';

/**
 * Request body of the logo and banner routes, the `PictureUpdate` schema.
 */
export type PictureUpdate = {
    /**
     * The picture: a confirmed asset of the slot's purpose (`partner_logo`, square; `partner_banner`, twice as wide as tall), or `null` to remove it.
     */
    asset_id?: string | null;
};

/**
 * A Partner's plan, held on the Partner until platform-configuration owns plans: Starter (INR 0), Standard (INR 1,999) and Pro (INR 4,999) a month before GST.
 */
export type Plan = 'starter' | 'standard' | 'pro';

/**
 * One of the plans as offered, the `PlanOffer` schema.
 */
export type PlanOffer = {
    /**
     * The plan.
     */
    plan: Plan;
    /**
     * Its name.
     */
    label: string;
    /**
     * The monthly fee in paise, before GST.
     */
    monthly_fee: number;
    /**
     * The kinds of Service it includes.
     */
    kinds: Array<ServiceKind>;
    /**
     * Whether its stores may use the platform fleet.
     */
    platform_fleet: boolean;
};

/**
 * A Partner's plan, the `PartnerPlan` schema: the plan with what it includes, the trial, a change waiting, and the plans on offer.
 */
export type PartnerPlan = {
    /**
     * The plan in force, with what it includes.
     */
    current: PlanOffer;
    /**
     * The plan the Partner chose for after the trial; Starter unless chosen.
     */
    plan_after_trial: Plan;
    /**
     * The plans on offer.
     */
    plans: Array<PlanOffer>;
    /**
     * A change platform staff scheduled.
     */
    scheduled?: ScheduledPlanChange | null;
    /**
     * The Pro trial, once the Partner has had one.
     */
    trial?: PlanTrial | null;
};

/**
 * The Pro trial of a Partner, the `PlanTrial` schema.
 */
export type PlanTrial = {
    /**
     * When it ends.
     */
    ends_at: string;
    /**
     * The plan the Partner moves to then.
     */
    then: Plan;
    /**
     * `true` while it runs.
     */
    running: boolean;
};

/**
 * A plan change waiting for its moment, the `ScheduledPlanChange` schema.
 */
export type ScheduledPlanChange = {
    /**
     * The plan it moves to.
     */
    plan: Plan;
    /**
     * When.
     */
    effective_at: string;
    /**
     * Why, as platform staff gave it.
     */
    reason?: string | null;
    /**
     * Who scheduled it.
     */
    scheduled_by?: string | null;
};

/**
 * What moving a Partner to a plan would do, the `PlanImpact` schema: shown to platform staff before they confirm.
 */
export type PlanImpact = {
    /**
     * The plan in force.
     */
    from: Plan;
    /**
     * The plan proposed.
     */
    to: Plan;
    /**
     * The kinds the proposed plan lacks.
     */
    kinds_lost: Array<ServiceKind>;
    /**
     * The Services that would be disabled, enabled or awaiting documents now.
     */
    services: Array<PlanImpactService>;
    /**
     * `false` when its stores would lose the platform fleet.
     */
    platform_fleet: boolean;
};

/**
 * A Service a plan change would stop, the `PlanImpactService` schema.
 */
export type PlanImpactService = {
    /**
     * The Service.
     */
    id: string;
    /**
     * Its kind.
     */
    kind: ServiceKind;
    /**
     * Its name.
     */
    name: string;
    /**
     * The Locations where it would stop.
     */
    location_ids: Array<string>;
};

/**
 * Request body of `PUT /v1/partners/{partner_id}/plan`, the `PartnerPlanUpdate` schema.
 */
export type PartnerPlanUpdate = {
    /**
     * When the move takes effect; now when absent.
     */
    effective_at?: string | null;
    /**
     * The plan to move to; platform staff only, with a reason. The plan in force cancels a change waiting.
     */
    plan?: Plan | null;
    /**
     * The plan to move to when the trial ends; `plan:write` (the owner), or platform staff.
     */
    plan_after_trial?: Plan | null;
    /**
     * Why.
     */
    reason?: string | null;
};

/**
 * A compliance document on file, the `PartnerDocument` schema.
 */
export type PartnerDocument = {
    /**
     * Identifier of the document.
     */
    id: string;
    /**
     * The Partner it belongs to.
     */
    partner_id: string;
    /**
     * What it is.
     */
    kind: DocumentKind;
    /**
     * The uploaded file (purpose `partner_document`, restricted): read it through `GET /v1/assets/{asset_id}/link`.
     */
    asset_id: string;
    /**
     * Where its review is.
     */
    review: ReviewState;
    /**
     * When it was filed.
     */
    uploaded_at: string;
    /**
     * The version, raised on every review.
     */
    version: number;
    /**
     * The last day it is valid.
     */
    expires_on?: string | null;
    /**
     * When it was issued.
     */
    issued_on?: string | null;
    /**
     * A label, for example the outlet a licence names.
     */
    label?: string | null;
    /**
     * The number the document carries, for example the licence number.
     */
    number?: string | null;
    /**
     * The reviewer's note; always present on a rejection.
     */
    review_note?: string | null;
    /**
     * When it was reviewed.
     */
    reviewed_at?: string | null;
    /**
     * Who reviewed it.
     */
    reviewed_by?: string | null;
    /**
     * Who filed it.
     */
    uploaded_by?: string | null;
};

/**
 * The kind of a compliance document.
 */
export type DocumentKind = 'gst_registration' | 'fssai_licence' | 'shop_establishment' | 'pan' | 'identity' | 'bank_proof' | 'other';

/**
 * Where a document's review is.
 */
export type ReviewState = 'pending' | 'approved' | 'rejected';

/**
 * One requirement and where it stands, the `DocumentRequirement` schema.
 */
export type DocumentRequirement = {
    /**
     * The kind required.
     */
    kind: DocumentKind;
    /**
     * Where it stands.
     */
    state: RequirementState;
    /**
     * `true` within thirty days of the expiry of a satisfied requirement.
     */
    expiring: boolean;
    /**
     * What it does to trading.
     */
    trading: TradingEffect;
    /**
     * Which Locations it covers.
     */
    covers: RequirementCoverage;
    /**
     * The document that decides it, when one is on file.
     */
    document_id?: string | null;
    /**
     * The deciding document's last valid day.
     */
    expires_on?: string | null;
    /**
     * The reviewer's note of a rejection.
     */
    review_note?: string | null;
    /**
     * The first day the covered Locations do not trade, in a grace period or once stopped.
     */
    stops_on?: string | null;
};

/**
 * Where a requirement stands.
 */
export type RequirementState = 'satisfied' | 'pending' | 'rejected' | 'expired' | 'missing';

/**
 * What a requirement does to trading.
 */
export type TradingEffect = 'trading' | 'grace' | 'awaiting_review' | 'stopped';

/**
 * Which Locations a requirement covers.
 */
export type RequirementCoverage = 'all_locations' | 'food_locations';

/**
 * Request body of `POST /v1/partners/{partner_id}/documents`, the `PartnerDocumentCreate` schema.
 */
export type PartnerDocumentCreate = {
    /**
     * What the document is.
     */
    kind: DocumentKind;
    /**
     * The uploaded file: an asset of the `partner_document` purpose, granted on `POST /v1/partners/{partner_id}/assets/grants` and confirmed.
     */
    asset_id: string;
    /**
     * Its last valid day; not before the issue date.
     */
    expires_on?: string | null;
    /**
     * When it was issued.
     */
    issued_on?: string | null;
    /**
     * A label, for example the outlet a licence names.
     */
    label?: string | null;
    /**
     * The number the document carries, for example the licence number.
     */
    number?: string | null;
};

/**
 * Request body of the review, the `PartnerDocumentReview` schema.
 */
export type PartnerDocumentReview = {
    /**
     * `approved`, or `rejected` with a note; an approval is withdrawn by a rejection.
     */
    outcome: ReviewState;
    /**
     * The note the Partner reads, at most 400 characters; required for a rejection.
     */
    note?: string | null;
};

/**
 * The documents on file and the requirements, the `PartnerDocumentList` schema.
 */
export type PartnerDocumentList = {
    /**
     * The documents on file, newest first.
     */
    items: Array<PartnerDocument>;
    /**
     * Every kind the Partner must have on file, with where it stands.
     */
    requirements: Array<DocumentRequirement>;
};

/**
 * A page of documents across Partners, the `PartnerDocumentPage` schema.
 */
export type PartnerDocumentPage = {
    /**
     * The documents, oldest first by default.
     */
    items: Array<PartnerDocument>;
    /**
     * Cursor of the next page, `null` on the last one.
     */
    next_cursor?: string | null;
};

/**
 * The payout account as every view shows it, the `PayoutAccount` schema: the number masked to its last four digits. Since contract 0.19.0 every write is checked by the payout provider's one-rupee transfer (`check`): a pass marks it verified, a different name or a failed transfer fails it with the reason. A change of an existing account holds payouts for at least 48 hours whatever verifies it; a first account is not a change.
 */
export type PayoutAccount = {
    /**
     * The account holder's name.
     */
    holder_name: string;
    /**
     * Business or personal.
     */
    account_type: PayoutAccountType;
    /**
     * The account number, all but the last four digits masked; sending it back unchanged keeps the account.
     */
    account_number: string;
    /**
     * The last four digits.
     */
    last4: string;
    /**
     * The IFSC.
     */
    ifsc: string;
    /**
     * Whether platform staff verified it.
     */
    state: PayoutAccountState;
    /**
     * When the Partner last changed it.
     */
    updated_at: string;
    /**
     * The version, raised on every write.
     */
    version: number;
    /**
     * The bank's name.
     */
    bank_name?: string | null;
    /**
     * Payouts wait until this moment after a change of account, and until it is verified.
     */
    payouts_held_until?: string | null;
    /**
     * The UPI ID.
     */
    upi_id?: string | null;
    /**
     * When it was verified.
     */
    verified_at?: string | null;
    /**
     * The one-rupee check of the account as it stands now; since contract 0.19.0.
     */
    check: PayoutAccountCheck;
    /**
     * Who verified it.
     */
    verified_by?: string | null;
};

/**
 * Request body of `PUT /v1/partners/{partner_id}/payout-account`, the `PayoutAccountUpdate` schema.
 */
export type PayoutAccountUpdate = {
    /**
     * The account holder's name.
     */
    holder_name: string;
    /**
     * Business or personal.
     */
    account_type: PayoutAccountType;
    /**
     * The IFSC: four letters, a zero and six letters or digits.
     */
    ifsc: string;
    /**
     * The account number, nine to eighteen digits; omitted, or the masked number sent back unchanged, keeps the account on file.
     */
    account_number?: string | null;
    /**
     * The bank's name.
     */
    bank_name?: string | null;
    /**
     * A UPI ID, optional.
     */
    upi_id?: string | null;
};

/**
 * Whether the account is verified, by the payout provider's one-rupee check since contract 0.19.0 or by platform staff by hand.
 */
export type PayoutAccountState = 'unverified' | 'verified';

/**
 * Whose account it is.
 */
export type PayoutAccountType = 'business' | 'personal';

/**
 * Who carries a store's deliveries.
 */
export type Carrier = 'own_agents' | 'platform_fleet' | 'external_carrier';

/**
 * Delivery as a store offers it, the `DeliveryMethod` schema.
 */
export type DeliveryMethod = {
    /**
     * Who carries the deliveries.
     */
    carrier: Carrier;
    /**
     * A delivery zone drawn as one ring of `[longitude, latitude]` points where a radius is the wrong shape; the resolved coverage radius applies without one. Switching delivery off discards it.
     */
    zone?: Array<Array<number>> | null;
};

/**
 * Pickup as a store offers it, the `PickupMethod` schema.
 */
export type PickupMethod = {
    /**
     * Minutes added to preparation before a collection is ready, 0 to 120.
     */
    ready_offset_minutes?: number;
};

/**
 * Dine-in as a store offers it, the `DineInMethod` schema: it needs tables, which arrive with dine-in.
 */
export type DineInMethod = {
    [key: string]: unknown;
};

/**
 * How orders leave a store, the `Fulfilment` schema: a method's presence enables it, and switching one off discards its settings.
 */
export type Fulfilment = {
    /**
     * Delivery, with its carrier and optional zone.
     */
    delivery?: DeliveryMethod | null;
    /**
     * Dine-in.
     */
    dine_in?: DineInMethod | null;
    /**
     * Pickup, with its ready offset.
     */
    pickup?: PickupMethod | null;
};

/**
 * How a store takes orders, the `OrderSettings` schema.
 */
export type OrderSettings = {
    /**
     * Minutes after which an order nobody accepted is declined; `null` means the platform's own limit. Platform staff's setting.
     */
    auto_reject_minutes?: number | null;
    /**
     * Cutlery at checkout.
     */
    cutlery?: Cutlery;
    /**
     * How preparation time is quoted.
     */
    preparation?: Preparation;
    /**
     * Whether an order may carry a prescription; platform staff's setting.
     */
    prescriptions?: boolean;
    /**
     * Scheduled orders.
     */
    scheduled?: ScheduledOrders;
    /**
     * The cutoff the evening before, HH:MM on the store's clock, 18:00 to 21:00; 20:00 by default. A change to a subscription's day counts only before it, and its deliveries are generated then. Since 0.24.0.
     */
    subscription_cutoff?: string;
};

/**
 * Request body of `PUT .../order-settings`, the `OrderSettingsUpdate` schema: absent members are kept.
 */
export type OrderSettingsUpdate = {
    /**
     * Minutes after which an order nobody accepted is declined, or `null` for the platform's own limit; platform staff only.
     */
    auto_reject_minutes?: number | null;
    /**
     * Cutlery at checkout.
     */
    cutlery?: Cutlery | null;
    /**
     * How preparation time is quoted.
     */
    preparation?: Preparation | null;
    /**
     * Whether an order may carry a prescription; platform staff only.
     */
    prescriptions?: boolean | null;
    /**
     * Scheduled orders; slot settings are refused while scheduled orders are not taken.
     */
    scheduled?: ScheduledOrdersUpdate | null;
    /**
     * A new cutoff, 18:00 to 21:00 (`subscription_cutoff_invalid`). Since 0.24.0.
     */
    subscription_cutoff?: string;
};

/**
 * How preparation time is quoted, the `Preparation` schema.
 */
export type Preparation = {
    /**
     * Typed or measured.
     */
    mode: PreparationMode;
    /**
     * The typed minutes, the quote in fixed mode and the fallback in measured mode.
     */
    minutes: number;
};

/**
 * How preparation time is quoted.
 */
export type PreparationMode = 'fixed' | 'measured';

/**
 * How a store takes scheduled orders, the `ScheduledOrders` schema.
 */
export type ScheduledOrders = {
    /**
     * Whether scheduled orders are taken; switching off keeps the slot settings.
     */
    accepts: boolean;
    /**
     * The slot length, 15, 30 or 60 minutes; platform staff's setting.
     */
    slot_minutes: number;
    /**
     * How many days ahead orders are taken, 1 to 7.
     */
    window_days: number;
    /**
     * Most orders per slot, `null` for no cap; platform staff's setting.
     */
    cap_per_slot?: number | null;
};

/**
 * Scheduled orders as changed, the `ScheduledOrdersUpdate` schema: absent members are kept.
 */
export type ScheduledOrdersUpdate = {
    /**
     * Whether scheduled orders are taken; switching off keeps the slot settings.
     */
    accepts?: boolean | null;
    /**
     * Most orders per slot, or `null` for no cap; platform staff only.
     */
    cap_per_slot?: number | null;
    /**
     * The slot length, 15, 30 or 60 minutes; platform staff only.
     */
    slot_minutes?: number | null;
    /**
     * How many days ahead, 1 to 7, the platform's limit.
     */
    window_days?: number | null;
};

/**
 * Whether checkout asks about cutlery and what saying yes costs, the `Cutlery` schema.
 */
export type Cutlery = {
    /**
     * Checkout asks.
     */
    asks: boolean;
    /**
     * What saying yes costs, in minor units of the Location's currency.
     */
    fee: number;
};

/**
 * How a store appears, apart from how it operates, the `Listing` schema. A value with a default: a store opened before it existed reads as reviewable and unmarked.
 */
export type Listing = {
    /**
     * The marks the storefront draws on its card; platform staff only.
     */
    highlights?: Array<Highlight>;
    /**
     * Whether customers may rate and review it; off hides the option and what is written.
     */
    reviews?: boolean;
    /**
     * Search tags, lower cased and de-duplicated.
     */
    tags?: Array<string>;
};

/**
 * A mark the storefront draws on a store's card and shelves it by; platform staff only.
 */
export type Highlight = 'exclusive' | 'premium';

/**
 * A store's pause, the `LocationPause` schema: who paused it, why and until when.
 */
export type Pause = {
    /**
     * When it takes orders again, by itself.
     */
    until: string;
    /**
     * Why.
     */
    reason: PauseReason;
    /**
     * When.
     */
    paused_at: string;
    /**
     * The message customers read, for a custom reason.
     */
    message?: string | null;
    /**
     * Who paused it.
     */
    paused_by?: string | null;
};

/**
 * Request body of `POST .../pause`, the `LocationPause` schema.
 */
export type LocationPause = {
    /**
     * How long, one minute to a day (1440 minutes); the console offers 15, 30 and 60.
     */
    minutes: number;
    /**
     * Why: high demand, or a custom message customers read.
     */
    reason: PauseReason;
    /**
     * The message customers read, at most 200 characters; required for a custom reason.
     */
    message?: string | null;
};

/**
 * Why a store is paused.
 */
export type PauseReason = 'high_demand' | 'custom';

/**
 * What a Location is doing now, the `LocationLive` schema: resolved at one instant per read.
 */
export type LocationLive = {
    /**
     * The effective state.
     */
    state: LocationLiveState;
    /**
     * The preparation minutes the store quotes now.
     */
    preparation_minutes: number;
    /**
     * The instant this answer is for.
     */
    at: string;
    /**
     * The pause in force, with who, why and until when.
     */
    pause?: Pause | null;
    /**
     * Why it is not online: `paused`, `closed`, `location_pending`, `location_suspended`, `archived`, `partner_pending`, `partner_suspended`, `partner_archived`, `documents`, `not_selling`.
     */
    reason?: string | null;
    /**
     * When the state changes, when known: the end of a pause, the next opening or closing.
     */
    until?: string | null;
};

/**
 * What a Location is doing now.
 */
export type LocationLiveState = 'online' | 'closed' | 'offline' | 'not_live';

/**
 * What a Location is, by what it runs: a store sells (a product-sales Service is on there), a branch only operates (a delivery depot, a field Service's base). Never chosen by hand.
 */
export type ReadsAs = 'store' | 'branch';

/**
 * What going live needs for a Location, the `LocationActivation` schema.
 */
export type LocationActivation = {
    /**
     * The Location's status.
     */
    status: LocationStatus;
    /**
     * `true` when nothing blocks it going live.
     */
    ready: boolean;
    /**
     * What stands in the way, each with its code; the same blockers an activation is refused with.
     */
    blockers: Array<Blocker>;
};

/**
 * A holiday of the Location's country offered as a closure, the `HolidayOffer` schema.
 */
export type HolidayOffer = {
    /**
     * The date.
     */
    date: string;
    /**
     * Its name.
     */
    name: string;
    /**
     * `true` when the Location is already closed that day, by its own closure or one set on its zone, city or country.
     */
    covered: boolean;
    /**
     * Who closed it, when covered: the layer's label.
     */
    covered_by?: string | null;
};

/**
 * The holidays offered, the `HolidayOfferList` schema.
 */
export type HolidayOfferList = {
    /**
     * Upcoming public holidays of the Location's country, oldest first.
     */
    items: Array<HolidayOffer>;
};

/**
 * A Service switched on at a Location as the Location reads it, the `LocationService` schema.
 */
export type LocationService = {
    /**
     * The Service.
     */
    id: string;
    /**
     * Its kind.
     */
    kind: ServiceKind;
    /**
     * Its name.
     */
    name: string;
    /**
     * Its status.
     */
    status: ServiceStatus;
    /**
     * Whether it trades here now.
     */
    trading: boolean;
};

/**
 * A delivery Service's pricing as a Provider, the `DeliveryPricing` schema: a flat fee per delivery, a per-kilometre charge beyond a base distance in ascending bands, and an optional waiting fee; every amount in minor units of `currency`.
 */
export type DeliveryPricing = {
    /**
     * The currency of every amount.
     */
    currency: string;
    /**
     * The fee per delivery.
     */
    flat_fee: number;
    /**
     * The distance the flat fee covers, in metres.
     */
    base_distance_metres: number;
    /**
     * The per-kilometre charge beyond it, in ascending bands ending open-ended.
     */
    per_km: Array<KilometreBand>;
    /**
     * The minutes of waiting included.
     */
    free_waiting_minutes?: number;
    /**
     * The fee per minute of waiting beyond the free minutes, when charged.
     */
    waiting_fee_per_minute?: number | null;
};

/**
 * One band of the per-kilometre charge beyond the base distance, the `KilometreBand` schema.
 */
export type KilometreBand = {
    /**
     * The charge per kilometre in the band, in minor units.
     */
    per_km: number;
    /**
     * The band's upper bound in metres from the pickup; `null` for the open-ended last band.
     */
    up_to_metres?: number | null;
};

/**
 * A quote and how it was reached, the `DeliveryQuote` schema.
 */
export type DeliveryQuote = {
    /**
     * The pricing version it was priced at, which the delivery keeps.
     */
    version: number;
    /**
     * The currency.
     */
    currency: string;
    /**
     * The distance priced, in metres.
     */
    distance_metres: number;
    /**
     * The minutes of waiting priced.
     */
    waiting_minutes: number;
    /**
     * The flat fee.
     */
    flat_fee: number;
    /**
     * The per-kilometre charge beyond the base distance.
     */
    distance_charge: number;
    /**
     * The waiting charge.
     */
    waiting_charge: number;
    /**
     * The total, in minor units.
     */
    total: number;
};

/**
 * A version of a delivery Service's pricing, the `DeliveryPricingVersion` schema.
 */
export type DeliveryPricingVersion = {
    /**
     * The Service.
     */
    service_id: string;
    /**
     * The version, from 1; every delivery keeps the version it was quoted at.
     */
    version: number;
    /**
     * The pricing.
     */
    pricing: DeliveryPricing;
    /**
     * When it was made.
     */
    created_at: string;
    /**
     * Who made it.
     */
    created_by?: string | null;
};

/**
 * Request body of `PUT .../services/{service_id}/pricing`, the `DeliveryPricingUpdate` schema: the next version of the pricing.
 */
export type DeliveryPricingUpdate = {
    /**
     * The pricing.
     */
    pricing: DeliveryPricing;
    /**
     * Why; required of platform staff acting for the Partner.
     */
    reason?: string | null;
};

/**
 * A field Service's settings at one Location, the `FieldServiceSettings` schema: bookable work around it. Changing them never moves or cancels a booking already made.
 */
export type FieldServiceSettings = {
    /**
     * Where it takes bookings.
     */
    area?: FieldArea;
    /**
     * How far ahead bookings are taken, in days, up to 60.
     */
    booking_window_days?: number;
    /**
     * The buffer between jobs, in minutes.
     */
    buffer_minutes?: number;
    /**
     * Its working hours; empty means the Location's hours.
     */
    hours?: Array<DaySchedule>;
    /**
     * The notice a booking needs before its slot, in minutes.
     */
    min_notice_minutes?: number;
    /**
     * The slot length, 15, 30 or 60 minutes.
     */
    slot_minutes?: number;
};

/**
 * Where a field Service takes bookings around a Location, the `FieldArea` schema.
 */
export type FieldArea = {
    /**
     * A drawn polygon, one ring of `[longitude, latitude]` points, in place of the radius.
     */
    polygon?: Array<Array<number>> | null;
    /**
     * A radius around the Location, in kilometres, up to 25; 10 by default.
     */
    radius_km?: number | null;
    /**
     * The Location's whole zone, in place of either.
     */
    whole_zone?: boolean;
};

/**
 * A kind and where it stands for the Partner, the `KindAvailability` schema.
 */
export type KindAvailability = {
    /**
     * The kind.
     */
    kind: ServiceKind;
    /**
     * Where it stands.
     */
    state: KindState;
    /**
     * The Services of the kind, whatever their status.
     */
    services: number;
    /**
     * The lowest plan that includes it, when the Partner's does not.
     */
    plan_needed?: Plan | null;
};

/**
 * Where a kind of Service stands for a Partner.
 */
export type KindState = 'enabled' | 'awaiting_documents' | 'disabled' | 'available' | 'not_in_plan';

/**
 * A Service at one Location, the `ServiceAtLocation` schema.
 */
export type ServiceAtLocation = {
    /**
     * The Service.
     */
    service_id: string;
    /**
     * The Location.
     */
    location_id: string;
    /**
     * Whether the Service is switched on there.
     */
    switched_on: boolean;
    /**
     * Whether it is on there because it is on everywhere.
     */
    everywhere: boolean;
    /**
     * Whether it trades there now.
     */
    trading: boolean;
    /**
     * For a field Service: its bookable area, hours and slots there, defaults filled in.
     */
    settings?: FieldServiceSettings | null;
};

/**
 * Request body of `POST /v1/partners/{partner_id}/services`, the `ServiceCreate` schema.
 */
export type ServiceCreate = {
    /**
     * What the Service is.
     */
    kind: ServiceKind;
    /**
     * Its configuration by kind: `ProductSalesConfig`, `FieldServiceConfig` or `DeliveryConfig`; `{}` when absent.
     */
    config?: {
        [key: string]: unknown;
    } | null;
    /**
     * `false` registers it disabled; enabled by default, awaiting documents while its kind needs some not approved.
     */
    enabled?: boolean;
    /**
     * Switched on at every Location, present and future; the default when `location_ids` is absent.
     */
    everywhere?: boolean | null;
    /**
     * The Locations to switch it on at; `[]` switches it on nowhere.
     */
    location_ids?: Array<string> | null;
    /**
     * Its name, 1 to 100 characters; the kind's when absent.
     */
    name?: string | null;
    /**
     * Why; required of platform staff acting for the Partner.
     */
    reason?: string | null;
};

/**
 * Request body of `PUT .../services/{service_id}/locations/{location_id}`, the `ServiceLocationUpdate` schema.
 */
export type ServiceLocationUpdate = {
    /**
     * Why; required of platform staff acting for the Partner.
     */
    reason?: string | null;
    /**
     * For a field Service, its area, hours and slots at the Location, defaults filled in for absent members; absent for any other kind.
     */
    settings?: FieldServiceSettings | null;
};

/**
 * Request body of `PATCH /v1/partners/{partner_id}/services/{kind}`, the `ServiceUpdate` schema: absent members are kept.
 */
export type ServiceUpdate = {
    /**
     * A configuration replacing the stored one as a whole.
     */
    config?: {
        [key: string]: unknown;
    } | null;
    /**
     * `true` switches it on at every Location; `false` keeps it on where it is, one by one.
     */
    everywhere?: boolean | null;
    /**
     * Switches it on at exactly these Locations.
     */
    location_ids?: Array<string> | null;
    /**
     * A new name.
     */
    name?: string | null;
    /**
     * Why; required of platform staff acting for the Partner.
     */
    reason?: string | null;
    /**
     * `enabled` or `disabled`; disabling keeps the configuration, re-enabling restores it.
     */
    status?: ServiceStatus | null;
};

/**
 * A product-sales Service's configuration, the `ProductSalesConfig` schema.
 */
export type ProductSalesConfig = {
    /**
     * What it sells; `general` when absent.
     */
    catalogue_type?: CatalogueType;
};

/**
 * A field Service's configuration, the `FieldServiceConfig` schema: the bookable work itself, with its durations and prices, is the services catalogue.
 */
export type FieldServiceConfig = {
    /**
     * The qualifications the Partner names, which its agents hold and its bookable work requires.
     */
    qualifications?: Array<string>;
    /**
     * The reference service type's code, lower case (`salon`, `repairs`, `laundry`, `cleaning`).
     */
    service_type?: string | null;
};

/**
 * A delivery Service's configuration as a Provider, the `DeliveryConfig` schema.
 */
export type DeliveryConfig = {
    /**
     * The radius around its depot Locations it covers, in kilometres, when no zones are drawn.
     */
    coverage_radius_km?: number | null;
    /**
     * Its operating hours per weekday; empty means it follows its depot Locations' hours.
     */
    hours?: Array<DaySchedule>;
    /**
     * Most tasks an agent carries at once.
     */
    max_concurrent_tasks?: number;
    /**
     * Whether it takes on-demand work.
     */
    on_demand?: boolean;
    /**
     * Whether other Partners may ask it for deliveries, or it serves only its own Locations.
     */
    open_to_partners?: boolean;
    /**
     * Whether it takes scheduled work.
     */
    scheduled?: boolean;
    /**
     * The notice scheduled work needs, in minutes.
     */
    scheduled_notice_minutes?: number;
    /**
     * The vehicles it runs.
     */
    vehicle_types?: Array<VehicleType>;
    /**
     * Zones it serves, each one ring of `[longitude, latitude]` points.
     */
    zones?: Array<Array<Array<number>>>;
};

/**
 * A vehicle type with what it carries, the `VehicleType` schema.
 */
export type VehicleType = {
    /**
     * The vehicle.
     */
    kind: VehicleKind;
    /**
     * The heaviest parcel, in kilograms.
     */
    max_weight_kg: number;
    /**
     * The bulkiest parcel, in litres.
     */
    max_volume_litres: number;
};

/**
 * A vehicle a delivery Service runs.
 */
export type VehicleKind = 'bicycle' | 'two_wheeler' | 'three_wheeler' | 'four_wheeler';

/**
 * What a product-sales Service sells, deciding what its items collect and the documents it needs: the store types of the reference data, and `general` for none of them.
 */
export type CatalogueType = 'food' | 'bakery' | 'drinks' | 'grocery' | 'pharmacy' | 'retail' | 'general';

/**
 * Who performed an audited act. A signed-in person, with the membership they acted under and their name frozen at the time, or the system for timers and provider notices. While a platform member views a partner's console with an owner's consent, the member is the actor and the owner acted as is `on_behalf_of_user_id`; the owner is never recorded as the actor.
 */
export type AuditActor = {
    /**
     * A person or the system.
     */
    kind: 'user' | 'system';
    /**
     * The user, for a person.
     */
    user_id: string | null;
    /**
     * The membership acted under, when known.
     */
    membership_id: string | null;
    /**
     * The partner the membership is in; the platform organisation for platform staff.
     */
    partner_id: string | null;
    /**
     * The actor's name as it was at the time; for a person recorded without one, their name now when the reader may see it.
     */
    label: string | null;
    /**
     * The person the actor acted as, while impersonating them with their consent; `null` otherwise.
     */
    on_behalf_of_user_id: string | null;
};

/**
 * The record an audited act was about, as a reference rather than a copy.
 */
export type AuditTarget = {
    /**
     * The kind of record, for example `partner`, `membership`, `country` or `service_area`.
     */
    kind: string;
    /**
     * The record's id, a UUID or a natural key such as a country code.
     */
    id: string;
    /**
     * The record's display label at the time, when known.
     */
    label: string | null;
};

/**
 * One entry of the audit log: a privileged act, appended when the act
 * committed and never changed or deleted afterwards. Privileged acts are
 * every act under a platform permission, every change to roles, grants and
 * memberships, every suspension and reactivation, every refund, payout
 * release and correction, every impersonation and every change to
 * reference data.
 *
 */
export type AuditEntry = {
    /**
     * Unique identifier of the entry, a UUID version 7; entries sort by it.
     */
    id: string;
    /**
     * When the act happened, as an RFC 3339 timestamp in UTC.
     */
    occurred_at: string;
    /**
     * Who acted.
     */
    actor: AuditActor;
    /**
     * The client address the request came from, when known.
     */
    client_address: string | null;
    /**
     * What was done, as `<module>.<entity>.<act>`.
     */
    action: string;
    /**
     * The record acted on.
     */
    target: AuditTarget;
    /**
     * The partner the record belongs to; `null` for platform records such as countries.
     */
    partner_id: string | null;
    /**
     * The values before the act, when the act changed something.
     */
    before: {
        [key: string]: unknown;
    } | null;
    /**
     * The values after the act, when the act changed something.
     */
    after: {
        [key: string]: unknown;
    } | null;
    /**
     * The reason given, where the capability demands one.
     */
    reason: string | null;
    /**
     * The correlation id of the request, the value of its `X-Correlation-Id`.
     */
    correlation_id: string | null;
    /**
     * The person who proposed, for a four-eyes approval.
     */
    proposer_user_id: string | null;
    /**
     * The person who approved, for a four-eyes approval.
     */
    approver_user_id: string | null;
};

/**
 * A page of audit entries, the response of `GET /v1/audit-log`.
 */
export type AuditEntryList = {
    /**
     * The entries on this page, newest first unless sorted otherwise.
     */
    items: Array<AuditEntry>;
    /**
     * An opaque cursor to pass as `cursor` for the next page, or `null` when this is the last page.
     */
    next_cursor: string | null;
    /**
     * Facet counts, present when `facets` was asked for.
     */
    facets?: Array<Facet>;
};

/**
 * A role held by a member at one scope: the whole partner, one Location or one Service of it, or the platform. A member may hold several grants; each lists the permissions held at its scope, never merged with another's.
 */
export type AccessGrant = {
    /**
     * Unique identifier of the grant.
     */
    id: string;
    /**
     * The role granted.
     */
    role_id: string;
    /**
     * The role's name.
     */
    role_name: string;
    /**
     * Whether the role is maintained by the platform, a default every partner receives, or the realm's own.
     */
    role_kind: RoleKind;
    /**
     * Where the role applies.
     */
    scope: AccessScope;
    /**
     * The permissions held at that scope, sorted: the role's, within the partner's entitlements.
     */
    permissions: Array<string>;
    /**
     * When it was granted, as an RFC 3339 timestamp in UTC.
     */
    granted_at: string;
    /**
     * Who granted it; `null` when the platform did, at onboarding or provisioning.
     */
    granted_by?: string | null;
};

/**
 * The request body of `POST /v1/partners/{partner_id}/members/{membership_id}/grants`: a role of the partner, at the whole partner or at one of its Locations or Services.
 */
export type AccessGrantCreate = {
    /**
     * The role to grant, a role of the partner.
     */
    role_id: string;
    /**
     * A Location of the partner, to hold the role there only.
     */
    location_id?: string | null;
    /**
     * A Service of the partner, to hold the role there only; an `AGENT` role is held at its own Service.
     */
    service_id?: string | null;
};

/**
 * A member's grants after a change, the response of `PUT /v1/partners/{partner_id}/members/{membership_id}/access`.
 */
export type AccessGrantList = {
    /**
     * Every grant of the member after the change.
     */
    items: Array<AccessGrant>;
};

/**
 * One entry of the access history: a role granted or revoked, by whom, to whom, at what scope. The history is append-only and outlives the roles and memberships it names.
 */
export type AccessHistoryEntry = {
    /**
     * Unique identifier of the entry.
     */
    id: string;
    /**
     * When it happened, as an RFC 3339 timestamp in UTC.
     */
    occurred_at: string;
    /**
     * Whether the role was granted or revoked.
     */
    action: HistoryAction;
    /**
     * The realm: the partner, or the platform organisation for platform staff.
     */
    partner_id: string;
    /**
     * The person the grant is held by.
     */
    user_id: string;
    /**
     * The membership the grant is held through.
     */
    membership_id: string;
    /**
     * The role.
     */
    role_id: string;
    /**
     * The role's name at the time.
     */
    role_name: string;
    /**
     * Where the grant applies.
     */
    scope: AccessScope;
    /**
     * Who acted; `null` when the platform did.
     */
    actor_user_id?: string | null;
};

/**
 * A page of the access history, newest first.
 */
export type AccessHistoryList = {
    /**
     * The entries of the page.
     */
    items: Array<AccessHistoryEntry>;
    /**
     * The cursor of the next page; `null` on the last one.
     */
    next_cursor?: string | null;
};

/**
 * What happened to a grant in the access history: `granted` or `revoked`. Clients must tolerate values they do not know.
 */
export type HistoryAction = 'granted' | 'revoked';

/**
 * A named set of permissions, owned by the platform or by one partner. `maintained` roles (`SUPER_ADMIN`, `OWNER`) are kept by the platform and offer neither editing nor deletion; `default` roles (a partner's `MANAGER`, `STAFF`, `DISPATCHER` and `KITCHEN`, the `AGENT` role of each agent-based Service, and the platform's narrower staff roles) are tuned but neither renamed nor deleted; `custom` roles belong to the realm that defined them.
 */
export type AccessRole = {
    /**
     * Unique identifier of the role.
     */
    id: string;
    /**
     * The role's name, unique within its owner regardless of case.
     */
    name: string;
    /**
     * `maintained`, `default` or `custom`.
     */
    kind: RoleKind;
    /**
     * `true` for the roles the platform keeps (`SUPER_ADMIN`, `OWNER`): a console offers neither editing nor deletion.
     */
    maintained: boolean;
    /**
     * Whether the permissions may be changed: every role but a maintained one.
     */
    permissions_editable: boolean;
    /**
     * Whether the role may be renamed and deleted: custom roles, and deleted only while nobody holds them.
     */
    deletable: boolean;
    /**
     * The permissions, sorted.
     */
    permissions: Array<string>;
    /**
     * How many grants of the role exist, enabled members or not.
     */
    holders: number;
    /**
     * Raised on every change; the entity tag of reads and the `If-Match` of changes.
     */
    version: number;
    /**
     * When the role was created, as an RFC 3339 timestamp in UTC.
     */
    created_at: string;
    /**
     * When the role last changed, as an RFC 3339 timestamp in UTC.
     */
    updated_at: string;
    /**
     * The partner that owns the role; `null` for a platform role.
     */
    partner_id?: string | null;
    /**
     * The Service an `AGENT` role was created with; `null` otherwise.
     */
    service_id?: string | null;
};

/**
 * The request body of `POST /v1/partners/{partner_id}/roles` and `POST /v1/platform/roles`: a new custom role. Every permission must be in the catalogue and the owner's pool, inside the partner's entitlements, and held by who acts.
 */
export type AccessRoleCreate = {
    /**
     * The role's name, unique within its owner regardless of case; `OWNER` and `SUPER_ADMIN` are reserved.
     */
    name: string;
    /**
     * The permissions the role holds.
     */
    permissions: Array<string>;
};

/**
 * The request body of the role changes: absent members are kept. A maintained role is refused (`role_maintained`); a default role takes new permissions but keeps its name.
 */
export type AccessRoleUpdate = {
    /**
     * A new name, for custom roles only.
     */
    name?: string | null;
    /**
     * The whole new set of permissions, replacing the old one.
     */
    permissions?: Array<string> | null;
};

/**
 * The roles of one owner, the platform or a partner, each with how many hold it.
 */
export type AccessRoleList = {
    /**
     * Maintained and default roles first, then the owner's own by name.
     */
    items: Array<AccessRole>;
};

/**
 * What a role is: `maintained` (kept by the platform), `default` (a tunable role every partner receives) or `custom` (the realm's own). Clients must tolerate values they do not know.
 */
export type RoleKind = 'maintained' | 'default' | 'custom';

/**
 * Where a grant applies: `platform` (platform staff only), `partner` (the whole partner and everything in it), `location` (one Location) or `service` (one Service). The identifiers that do not apply to the kind are `null`.
 */
export type AccessScope = {
    /**
     * The kind of scope.
     */
    kind: ScopeKind;
    /**
     * The Location, for `location`.
     */
    location_id?: string | null;
    /**
     * The partner, for every kind but `platform`.
     */
    partner_id?: string | null;
    /**
     * The Service, for `service`.
     */
    service_id?: string | null;
};

/**
 * The kind of scope a grant is held at: `platform`, `partner`, `location` or `service`. Clients must tolerate values they do not know.
 */
export type ScopeKind = 'platform' | 'partner' | 'location' | 'service';

/**
 * The request body of `PUT /v1/partners/{partner_id}/members/{membership_id}/access`: the member's whole access as one role, at the whole partner when no Location or Service is named, or at each one named. The difference from the current grants is applied as grants and revocations.
 */
export type AccessSet = {
    /**
     * The role, a role of the partner held by who acts.
     */
    role_id: string;
    /**
     * The Locations the role applies at; none named, and no Service, means the whole partner.
     */
    location_ids?: Array<string>;
    /**
     * The Services the role applies at.
     */
    service_ids?: Array<string>;
};

/**
 * A partner's entitlements: the permissions its roles may contain (the partner pool less what the platform withholds). Every role of the partner is cut to them at once when they shrink.
 */
export type Entitlements = {
    /**
     * The partner.
     */
    partner_id: string;
    /**
     * The permissions the partner's roles may contain, sorted.
     */
    granted: Array<string>;
    /**
     * What the platform withholds from the partner, sorted.
     */
    withheld: Array<string>;
};

/**
 * The request body of `PUT /v1/partners/{partner_id}/entitlements`: the whole set of permissions to withhold from the partner.
 */
export type EntitlementsUpdate = {
    /**
     * The permissions to withhold, from the partner pool; never `partner:access` (`partner_cannot_sign_in`).
     */
    withheld: Array<string>;
};

/**
 * Whether a membership admits its holder: `enabled`, or `disabled` (the member cannot enter the realm and keeps their grants for re-enabling). Clients must tolerate values they do not know.
 */
export type MembershipStatus = 'enabled' | 'disabled';

/**
 * One permission of the catalogue, `<entity>:<action>`, with the pools that may hold it.
 */
export type Permission = {
    /**
     * The permission's name, `<entity>:<action>`.
     */
    name: string;
    /**
     * What the permission allows, in a sentence a role editor shows.
     */
    summary: string;
    /**
     * Whether a partner's roles may contain it.
     */
    partner: boolean;
    /**
     * Whether platform roles may contain it.
     */
    platform: boolean;
};

/**
 * The permissions a role editor offers for one pool.
 */
export type PermissionList = {
    /**
     * The pool listed.
     */
    pool: PermissionPool;
    /**
     * The permissions, sorted by name.
     */
    items: Array<Permission>;
};

/**
 * Who may hold a permission: `platform` (platform roles), `partner` (a partner's roles) or `customer`. Clients must tolerate values they do not know.
 */
export type PermissionPool = 'platform' | 'partner' | 'customer';

/**
 * The request body of `POST /v1/platform/staff`: the person to invite into the platform. The membership grants nothing until a role is granted through a four-eyes proposal.
 */
export type PlatformStaffInvite = {
    /**
     * The email address to send the invitation to.
     */
    email: string;
    /**
     * The name the member will be shown under.
     */
    display_name?: string | null;
};

/**
 * A member of a partner's team, or of the platform's staff, with their status and every grant. `role` is the most senior default role held, or `custom`; the grants carry the whole truth.
 */
export type TeamMember = {
    /**
     * Unique identifier of the membership.
     */
    id: string;
    /**
     * The partner, or the platform organisation for platform staff.
     */
    partner_id: string;
    /**
     * The person.
     */
    user: User;
    /**
     * Whether the membership admits the member.
     */
    status: MembershipStatus;
    /**
     * The most senior default role held, or `custom`.
     */
    role: MembershipRole;
    /**
     * Every grant, each with its scope and the permissions held there.
     */
    grants: Array<AccessGrant>;
    /**
     * When the membership was created, as an RFC 3339 timestamp in UTC.
     */
    created_at: string;
    /**
     * When the membership was disabled, while it is; `null` otherwise.
     */
    disabled_at?: string | null;
    /**
     * How the member is shown in this realm: the name set for the membership, else the user's own.
     */
    display_name?: string | null;
};

/**
 * A team: the members of a partner, or the platform's staff.
 */
export type TeamMemberList = {
    /**
     * The members, oldest first, each with every grant.
     */
    items: Array<TeamMember>;
};

/**
 * The request body of the member changes: how the member is shown in this realm.
 */
export type TeamMemberUpdate = {
    /**
     * The name the member is shown under here, or `null` for the user's own.
     */
    display_name?: string | null;
};

/**
 * A four-eyes proposal: an act on a platform membership that a different platform member must approve before it runs. It expires undecided after seventy-two hours and is voided when what it names changes first.
 */
export type Approval = {
    /**
     * Unique identifier of the proposal.
     */
    id: string;
    /**
     * The act proposed.
     */
    action: ApprovalAction;
    /**
     * The platform membership the act is about.
     */
    membership_id: string;
    /**
     * The act's parameters, frozen when proposed: `role_id` for a grant, `grant_id` for a revocation, nothing else for the other acts.
     */
    parameters: unknown;
    /**
     * The platform member who proposed it.
     */
    proposed_by: string;
    /**
     * When it was proposed, as an RFC 3339 timestamp in UTC.
     */
    proposed_at: string;
    /**
     * When it expires undecided, seventy-two hours after it was proposed.
     */
    expires_at: string;
    /**
     * Where the proposal stands.
     */
    status: ApprovalStatus;
    /**
     * `true` when it ran at once because no other platform member could decide it; the audit log says so.
     */
    sole_decider: boolean;
    /**
     * When it was decided; `null` while pending.
     */
    decided_at?: string | null;
    /**
     * The platform member who decided it; `null` while pending.
     */
    decided_by?: string | null;
    /**
     * Why, as the decider said.
     */
    decision_reason?: string | null;
    /**
     * Why, as the proposer said.
     */
    reason?: string | null;
};

/**
 * An act that needs a second pair of eyes: granting a platform role, revoking one, turning a platform member's two-step sign-in off, or disabling a platform member. Clients must tolerate values they do not know.
 */
export type ApprovalAction = 'grant_platform_role' | 'revoke_platform_role' | 'reset_platform_two_step' | 'disable_platform_member';

/**
 * The request body of `POST /v1/platform/approvals`: the act, the platform membership it is about and its parameters.
 */
export type ApprovalCreate = {
    /**
     * The act proposed.
     */
    action: ApprovalAction;
    /**
     * The platform membership the act is about.
     */
    membership_id: string;
    /**
     * For `revoke_platform_role`: the grant to revoke.
     */
    grant_id?: string | null;
    /**
     * Why, shown to whoever decides.
     */
    reason?: string | null;
    /**
     * For `grant_platform_role`: the platform role to grant.
     */
    role_id?: string | null;
};

/**
 * The optional request body of the decisions on a proposal.
 */
export type ApprovalDecision = {
    /**
     * Why, as the decider says; the audit log keeps it.
     */
    reason?: string | null;
};

/**
 * Four-eyes proposals, newest first.
 */
export type ApprovalList = {
    /**
     * The proposals.
     */
    items: Array<Approval>;
};

/**
 * Where a proposal stands: `pending`, `approved`, `rejected`, `voided` (what it named changed, or its proposer left) or `expired` (undecided after seventy-two hours; never stored, a pending proposal past its expiry reads so). Clients must tolerate values they do not know.
 */
export type ApprovalStatus = 'pending' | 'approved' | 'rejected' | 'voided' | 'expired';

/**
 * Where a partner's consent to be viewed stands: `pending`, `approved` (for twenty-four hours), `rejected`, `revoked` (withdrawn by an owner, ending the sessions under it) or `expired`. Clients must tolerate values they do not know.
 */
export type ConsentStatus = 'pending' | 'approved' | 'rejected' | 'revoked' | 'expired';

/**
 * Requests to view a partner's console and the consents given, newest first.
 */
export type ImpersonationConsentList = {
    /**
     * The requests and consents.
     */
    items: Array<ImpersonationConsent>;
};

/**
 * A started or continued impersonation: the session, and an access token for the Partner console as the owner who consented, with the platform member named in its `act` claim.
 */
export type ImpersonationAccess = {
    /**
     * The impersonation session.
     */
    session: ImpersonationSession;
    /**
     * The access token for the Partner console. Changes answer `403` (`impersonation_read_only`) unless the consent allows them.
     */
    access_token: string;
    /**
     * Always `Bearer`.
     */
    token_type: 'Bearer';
    /**
     * Seconds until the token expires, never past the session's end; mint another at `POST /v1/platform/impersonation/sessions/{impersonation_id}/token` while the session runs.
     */
    expires_in: number;
};

/**
 * A platform member's request to view a partner's console, and the owner's decision on it. An approved consent lasts twenty-four hours, viewing only unless changes were asked for and allowed.
 */
export type ImpersonationConsent = {
    /**
     * Unique identifier of the request.
     */
    id: string;
    /**
     * The partner asked.
     */
    partner_id: string;
    /**
     * The platform member asking.
     */
    requested_by: string;
    /**
     * Why they ask, shown to the partner's owners.
     */
    reason: string;
    /**
     * Whether changes were asked for too.
     */
    writes_requested: boolean;
    /**
     * When they asked, as an RFC 3339 timestamp in UTC.
     */
    requested_at: string;
    /**
     * Where the consent stands.
     */
    status: ConsentStatus;
    /**
     * Whether changes are allowed; viewing only otherwise.
     */
    writes_allowed: boolean;
    /**
     * When an owner decided; `null` while pending.
     */
    decided_at?: string | null;
    /**
     * The owner who decided; `null` while pending.
     */
    decided_by?: string | null;
    /**
     * When an approved consent ends; `null` otherwise.
     */
    expires_at?: string | null;
};

/**
 * The optional request body of an owner's approval of a request to view the console.
 */
export type ImpersonationConsentApproval = {
    /**
     * `true` allows changes too, only when they were asked for; viewing only otherwise.
     */
    writes_allowed?: boolean;
};

/**
 * The request body of `POST /v1/platform/impersonation/consents`: the partner to view and why.
 */
export type ImpersonationConsentCreate = {
    /**
     * The partner whose console to view.
     */
    partner_id: string;
    /**
     * Why, shown to the partner's owners; required.
     */
    reason: string;
    /**
     * `true` asks to change things too; viewing only otherwise.
     */
    writes?: boolean;
};

/**
 * A platform member viewing a partner's console as the owner who consented: at most sixty minutes, never past the consent, readable by the platform and by the partner while it runs and after.
 */
export type ImpersonationSession = {
    /**
     * Unique identifier of the session.
     */
    id: string;
    /**
     * The consent it runs under.
     */
    consent_id: string;
    /**
     * The partner viewed.
     */
    partner_id: string;
    /**
     * The platform member viewing.
     */
    member_user_id: string;
    /**
     * The owner viewed as.
     */
    subject_user_id: string;
    /**
     * The member's reason.
     */
    reason: string;
    /**
     * Whether changes are allowed.
     */
    writes_allowed: boolean;
    /**
     * When it started, as an RFC 3339 timestamp in UTC.
     */
    started_at: string;
    /**
     * When it ends at the latest.
     */
    expires_at: string;
    /**
     * Whether it runs now.
     */
    live: boolean;
    /**
     * Why it ended: `ended` (by the member), `expired`, `consent_revoked` or `offboarded`; `null` while it runs.
     */
    end_reason?: 'ended' | 'expired' | 'consent_revoked' | 'offboarded' | null;
    /**
     * When it ended; `null` while it runs.
     */
    ended_at?: string | null;
};

/**
 * The request body of `POST /v1/platform/impersonation/sessions`: the approved consent to view under.
 */
export type ImpersonationSessionCreate = {
    /**
     * The approved consent, asked for by the caller.
     */
    consent_id: string;
    /**
     * Why now, when it differs from the consent request's reason.
     */
    reason?: string | null;
};

/**
 * Impersonation sessions, newest first.
 */
export type ImpersonationSessionList = {
    /**
     * The sessions.
     */
    items: Array<ImpersonationSession>;
};

/**
 * An agent's presence. `online` means the agent is on duty and its app was
 * heard from within the last 60 seconds; `busy` means online with a task
 * under way; `offline` means neither. Clients must tolerate values they do
 * not know, because a new status is an additive change.
 *
 */
export type AgentStatus = 'online' | 'busy' | 'offline';

/**
 * The last known position of an agent: WGS 84 coordinates, the heading and
 * speed reported with them, and the time the position was recorded on the
 * agent's device.
 *
 */
export type AgentPosition = {
    /**
     * Latitude in decimal degrees (WGS 84).
     */
    lat: number;
    /**
     * Longitude in decimal degrees (WGS 84).
     */
    lng: number;
    /**
     * Direction of travel in degrees clockwise from true north, or `null` when the device did not report one.
     */
    heading_deg: number | null;
    /**
     * Ground speed in metres per second, or `null` when the device did not report one.
     */
    speed_mps: number | null;
    /**
     * When the position was recorded on the device, as an RFC 3339 timestamp in UTC.
     */
    recorded_at: string;
};

/**
 * A person attached to one of a partner's services who executes tasks for
 * it. The agent is a membership in that service, not an identity: the same
 * person is a separate agent in every service they are attached to, each
 * with its own id, status and position.
 *
 */
export type Agent = {
    /**
     * Unique identifier of the agent.
     */
    id: string;
    /**
     * The partner whose service the agent is attached to.
     */
    partner_id: string;
    /**
     * The name the agent is shown under.
     */
    display_name: string;
    /**
     * The kind of service the agent is attached to.
     */
    service_kind: ServiceKind;
    /**
     * The agent's current working status.
     */
    status: AgentStatus;
    /**
     * When the agent was last heard from (a location ping or a status change), as an RFC 3339 timestamp in UTC, or `null` if never.
     */
    last_seen_at: string | null;
    /**
     * The agent's last known position, or `null` when the agent has not reported one yet.
     */
    position: AgentPosition | null;
    /**
     * What the agent moves with.
     */
    kind: AgentKind;
    /**
     * Whether the agent is on duty; positions are applied only on duty.
     */
    on_duty: boolean;
    /**
     * The zone the agent chose when going on duty, or `null` off duty.
     */
    zone_id: string | null;
    /**
     * The task under way, the next stop first, so a live map can show what a busy agent is doing; `null` when none.
     */
    current_task: AgentTaskBrief | null;
    /**
     * The service the agent works in, or `null` for an agent attached to none.
     */
    service_id: string | null;
    /**
     * The service's name, or `null` when the agent is attached to none or the name cannot be read now.
     */
    service_name: string | null;
};

/**
 * A list of agents, the response of `GET /v1/fleet/agents`.
 */
export type AgentList = {
    /**
     * The agents that match the request. The list is not paginated.
     */
    items: Array<Agent>;
};

/**
 * One position report from an agent's device. Pings are submitted in
 * batches with `POST /v1/fleet/location-pings` and applied per agent in
 * `recorded_at` order, so a device that buffered pings while it had no
 * connectivity can submit them together.
 *
 */
export type LocationPing = {
    /**
     * The agent the ping belongs to.
     */
    agent_id: string;
    /**
     * Latitude in decimal degrees (WGS 84).
     */
    lat: number;
    /**
     * Longitude in decimal degrees (WGS 84).
     */
    lng: number;
    /**
     * Direction of travel in degrees clockwise from true north. Omit it or send `null` when the device did not report one.
     */
    heading_deg?: number | null;
    /**
     * Ground speed in metres per second. Omit it or send `null` when the device did not report one.
     */
    speed_mps?: number | null;
    /**
     * When the position was recorded on the device, as an RFC 3339 timestamp in UTC.
     */
    recorded_at: string;
};

/**
 * The request body of `POST /v1/fleet/location-pings`. One batch carries between 1 and 500 pings, for one agent or several.
 */
export type LocationPingBatch = {
    /**
     * The pings to apply. Order within the batch does not matter; pings are applied per agent in `recorded_at` order.
     */
    pings: Array<LocationPing>;
};

/**
 * The response of `POST /v1/fleet/location-pings`, sent once the batch has been validated and queued.
 */
export type LocationPingsAccepted = {
    /**
     * The number of pings accepted for processing. They are applied after the response is sent; agents' positions and the live streams reflect them shortly after.
     */
    accepted: number;
    /**
     * The number of pings dropped and never kept because their agent is off duty. Present since contract 0.17.0.
     */
    dropped?: number;
};

/**
 * What an Agent moves with, which decides the documents the membership needs and what the Agent can carry: `walker` (10 kg), `bicycle` (15 kg), `two_wheeler` (25 kg), `van` (300 kg). A delivery service takes the kinds its vehicle types name (a walker always, a bicycle for `bicycle`, a two-wheeler for `two_wheeler`, a van for `four_wheeler`), every kind when it names none. Clients must tolerate values they do not know.
 */
export type AgentKind = 'walker' | 'bicycle' | 'two_wheeler' | 'van';

/**
 * Where an Agent membership stands: `invited` until the person accepts in the Agent app, `pending` until its documents are approved and the Partner activates it, `active` while the Agent may work, `suspended` when the Partner or Mission Control stopped it with a reason the Agent reads, `offboarded` when it ended, which is final. Clients must tolerate values they do not know.
 */
export type AgentMembershipStatus = 'invited' | 'pending' | 'active' | 'suspended' | 'offboarded';

/**
 * How an invitation reached the person: by SMS to a mobile number, or by email.
 */
export type AgentContactChannel = 'phone' | 'email';

/**
 * An onboarding document: `identity` for every kind of Agent; `driving_licence` and `vehicle_registration` for two-wheelers and vans; `police_verification` where the service requires it.
 */
export type AgentDocumentKind = 'identity' | 'driving_licence' | 'vehicle_registration' | 'police_verification';

/**
 * The government identity document an `identity` document is.
 */
export type IdentityDocumentType = 'aadhaar' | 'pan' | 'passport' | 'voter_id';

/**
 * Where a document stands: `uploaded` while its file is filed and not yet confirmed, `under_review` waiting for a reviewer, `approved`, `rejected` with a reason the Agent reads, `expired` once its expiry date has passed on the India calendar.
 */
export type AgentDocumentStatus = 'uploaded' | 'under_review' | 'approved' | 'rejected' | 'expired';

/**
 * A reviewer's decision on a document.
 */
export type AgentDocumentDecision = 'approve' | 'reject';

/**
 * The kind of stop a task is: `pickup` at the store, `drop_off` at the customer. Returns, appointments and on-site jobs come with later steps; clients must tolerate values they do not know.
 */
export type TaskKind = 'pickup' | 'drop_off';

/**
 * Where a task stands. It moves only forward: `accepted` (the Agent has it), `on_the_way`, `arrived`, then `completed`, or `failed` with a reason from the template's list. It also ends as `called_off` (the delivery was called off), `handed_back` (the Agent gave a direct assignment back within its minute) or `returned` (the membership was suspended or offboarded, or the duty closed, while it was under way).
 */
export type TaskStatus = 'accepted' | 'on_the_way' | 'arrived' | 'completed' | 'failed' | 'called_off' | 'handed_back' | 'returned';

/**
 * How the task reached the Agent: an `offer` the Agent accepted, or a `direct` assignment, which lands with a sound and may be handed back with a reason within 60 seconds of the app receiving it.
 */
export type TaskAssignment = 'offer' | 'direct';

/**
 * A step of a task's workflow, and what the Agent app records: `navigate` (starts towards the stop), `arrive` (within the stop's geofence, or with an override and its reason), `scan` (the order label's number), `photo`, `signature`, `code` (the customer's 4-digit code), `cash` (the amount collected), `notes`, and the two that end a task, `complete` and `fail`.
 */
export type TaskStepKind = 'navigate' | 'arrive' | 'scan' | 'photo' | 'signature' | 'code' | 'cash' | 'notes' | 'complete' | 'fail';

/**
 * A line of an Agent's pay: the base for a `pickup` or a `drop_off`, the `distance` at the rule's amount per kilometre, `waiting` beyond the free minutes at a pickup, the amount for a task `call_off` after the Agent started towards it, and the `tip` in full.
 */
export type EarningLineKind = 'pickup' | 'drop_off' | 'distance' | 'waiting' | 'call_off' | 'tip';

/**
 * Why a task paid: it was `completed`, it `failed_after_arrival` (a drop failed once the Agent had arrived pays its base and the distance), or it was `called_off` after the Agent started towards it.
 */
export type EarningOutcome = 'completed' | 'failed_after_arrival' | 'called_off';

/**
 * A piece of proof kept on a task: the `photo` at the door, a `signature`, the `scan` of the order label, the customer's `code` entered.
 */
export type ProofKind = 'photo' | 'signature' | 'scan' | 'code';

/**
 * Where a team's area comes from: the zones the service delivers in (`service_zones`), else the zones of the Locations it is switched on at (`location_zones`), else `none`.
 */
export type TeamAreaSource = 'service_zones' | 'location_zones' | 'none';

/**
 * Why an Agent cannot be activated, cannot go on duty or cannot take work: the membership is `not_active`, `suspended` or `offboarded`; a required document is `document_missing`, `document_pending` (under review), `document_rejected` or `document_expired`; the person is `on_duty_elsewhere` in another membership. Clients must tolerate values they do not know.
 */
export type AgentBlockerCode = 'not_active' | 'suspended' | 'offboarded' | 'document_missing' | 'document_pending' | 'document_rejected' | 'document_expired' | 'on_duty_elsewhere';

/**
 * Why a duty stretch ended: the Agent `switched_off`; nothing was heard from the app for 30 minutes (`silent`, closed at the last report); the membership was `suspended` or `offboarded`.
 */
export type DutyEndReason = 'switched_off' | 'silent' | 'suspended' | 'offboarded';

/**
 * A zone by id and name.
 */
export type ZoneRef = {
    /**
     * The zone (a service area of kind zone).
     */
    id: string;
    /**
     * Its name.
     */
    name: string;
};

/**
 * One reason an Agent cannot be activated, go on duty or take work, with the sentence a screen shows.
 */
export type AgentBlocker = {
    /**
     * What stands in the way.
     */
    code: AgentBlockerCode;
    /**
     * The reason in words, for the Agent or the Partner.
     */
    sentence: string;
    /**
     * The document concerned, for the document codes.
     */
    document_kind: AgentDocumentKind | null;
};

/**
 * A file of a document, stored privately (purpose `agent_document`); read it through the document's file link.
 */
export type AgentDocumentFile = {
    /**
     * The stored file.
     */
    asset_id: string;
    /**
     * Its safe name.
     */
    file_name: string;
    /**
     * Its type as the store reported it.
     */
    content_type: string;
    /**
     * Its size.
     */
    size_bytes: number;
};

/**
 * An onboarding document of an Agent membership, with its review. The number is shown to the Agent, to the Partner's members holding `agent:manage` for the service and to Mission Control, and never travels in an event.
 */
export type AgentDocument = {
    /**
     * The document.
     */
    id: string;
    /**
     * The Agent membership.
     */
    agent_id: string;
    /**
     * The Partner.
     */
    partner_id: string;
    /**
     * The delivery service.
     */
    service_id: string;
    /**
     * The Agent's name, for review queues.
     */
    agent_display_name: string;
    /**
     * The Partner's name, for Mission Control's queue.
     */
    partner_name: string | null;
    /**
     * What it is.
     */
    kind: AgentDocumentKind;
    /**
     * For an identity document, which one.
     */
    identity_type: IdentityDocumentType | null;
    /**
     * The document's number.
     */
    number: string | null;
    /**
     * Its expiry, for a licence and a registration.
     */
    expires_on: string | null;
    /**
     * For police verification, the date it was done.
     */
    verified_on: string | null;
    /**
     * Its files, one to four.
     */
    files: Array<AgentDocumentFile>;
    /**
     * Where it stands.
     */
    status: AgentDocumentStatus;
    /**
     * The reviewer's reason, which the Agent reads, when rejected.
     */
    rejection_reason: string | null;
    /**
     * When it was filed.
     */
    submitted_at: string;
    /**
     * When it was decided.
     */
    reviewed_at: string | null;
    /**
     * Who decided; `null` in the Agent app.
     */
    reviewed_by: string | null;
    /**
     * The reviewer's name; `null` in the Agent app.
     */
    reviewer_name: string | null;
    /**
     * Raised by one on every change.
     */
    version: number;
};

/**
 * An Agent membership's documents, newest first, with what the membership needs.
 */
export type AgentDocumentList = {
    /**
     * Every document filed, newest first.
     */
    items: Array<AgentDocument>;
    /**
     * Each document the membership needs and where it stands.
     */
    requirements: Array<AgentDocumentRequirement>;
};

/**
 * A page of documents waiting for review, oldest first.
 */
export type AgentDocumentPage = {
    /**
     * The documents.
     */
    items: Array<AgentDocument>;
    /**
     * The cursor of the next page; `null` on the last.
     */
    next_cursor: string | null;
};

/**
 * A document to file for the membership, once its files are posted with upload grants. The identity type and number are required for an identity document; the number and the expiry date for a licence and a registration; the date done for police verification.
 */
export type AgentDocumentSubmit = {
    /**
     * What it is.
     */
    kind: AgentDocumentKind;
    /**
     * For an identity document, which one.
     */
    identity_type?: IdentityDocumentType | null;
    /**
     * Its number: 12 digits for Aadhaar, five letters, four digits and a letter for PAN, a letter and seven digits for a passport, three letters and seven digits for a voter id; 5 to 20 letters and digits for a licence or a registration.
     */
    number?: string | null;
    /**
     * Its expiry, after today, for a licence and a registration.
     */
    expires_on?: string | null;
    /**
     * For police verification, the date it was done, not after today.
     */
    verified_on?: string | null;
    /**
     * The files, granted by `POST .../document-uploads` and posted to the store: one to four.
     */
    asset_ids: Array<string>;
};

/**
 * A reviewer's decision. A rejection needs a reason, which the Agent reads.
 */
export type AgentDocumentReview = {
    /**
     * Approve or reject.
     */
    decision: AgentDocumentDecision;
    /**
     * Why it is rejected: 1 to 500 characters, required to reject.
     */
    reason?: string | null;
};

/**
 * A file the Agent app is about to upload: what it reads of the file, checked against the purpose before any byte is sent.
 */
export type AgentUpload = {
    /**
     * The file name as the person has it.
     */
    file_name: string;
    /**
     * Its type: `application/pdf`, `image/png` or `image/jpeg` for a document; `image/jpeg`, `image/png` or `image/webp` for proof.
     */
    content_type: string;
    /**
     * Its size in bytes: at most 10 MB for a document, 8 MB for proof.
     */
    size_bytes: number;
};

/**
 * A proof file the Agent app is about to upload for a task.
 */
export type TaskProofUpload = {
    /**
     * A `photo` or a `signature`.
     */
    kind: ProofKind;
    /**
     * The file name.
     */
    file_name: string;
    /**
     * Its type: `image/jpeg`, `image/png` or `image/webp`.
     */
    content_type: string;
    /**
     * Its size in bytes, at most 8 MB.
     */
    size_bytes: number;
};

/**
 * Invites a person into one of the Partner's delivery services as an Agent of a kind, by mobile number (10 digits read as +91, or E.164) or by email. The person is told by message how to join.
 */
export type AgentInvite = {
    /**
     * The delivery service.
     */
    service_id: string;
    /**
     * What they will move with; one the service takes.
     */
    kind: AgentKind;
    /**
     * Their name as the Partner knows it, 1 to 100 characters; the first word is what customers read.
     */
    name: string;
    /**
     * Their mobile number; this or `email`.
     */
    phone?: string | null;
    /**
     * Their email; this or `phone`.
     */
    email?: string | null;
};

/**
 * The owner of an individual Partner joins their own delivery service as its Agent, with no invitation; the membership is pending its documents.
 */
export type AgentSelfJoin = {
    /**
     * The delivery service.
     */
    service_id: string;
    /**
     * What they move with.
     */
    kind: AgentKind;
};

/**
 * Changes an Agent membership: its name, or its kind, which puts an active membership back to pending until the new kind's documents are approved.
 */
export type AgentUpdate = {
    /**
     * The name, 1 to 100 characters.
     */
    display_name?: string | null;
    /**
     * The kind.
     */
    kind?: AgentKind | null;
};

/**
 * Why a membership is suspended or offboarded; the Agent reads it.
 */
export type AgentStatusReason = {
    /**
     * 1 to 500 characters.
     */
    reason: string;
};

/**
 * Lifts a suspension.
 */
export type AgentReinstatement = {
    /**
     * A note for the record, at most 500 characters.
     */
    note?: string | null;
};

/**
 * An invitation in progress, as the Partner sees it.
 */
export type AgentInvitationState = {
    /**
     * How the person was told.
     */
    channel: AgentContactChannel;
    /**
     * When it was last sent.
     */
    sent_at: string;
    /**
     * When it lapses; the Partner may send it again.
     */
    expires_at: string;
    /**
     * Whether it has lapsed.
     */
    expired: boolean;
    /**
     * Who invited.
     */
    invited_by: string | null;
};

/**
 * Where a task takes the Agent.
 */
export type TaskStop = {
    /**
     * The store's name, or the customer's first name.
     */
    name: string;
    /**
     * The address in words.
     */
    address: string | null;
    /**
     * The point the geofence is measured from.
     */
    point: GeoPoint;
    /**
     * The store, for a pickup.
     */
    location_id: string | null;
    /**
     * How near the Agent must be to arrive without an override.
     */
    geofence_metres: number;
};

/**
 * An Agent's current task in short, for live maps and lists: the delivery, the order with its number and the stop the Agent is heading to.
 */
export type AgentTaskBrief = {
    /**
     * The task.
     */
    task_id: string;
    /**
     * The delivery.
     */
    delivery_id: string;
    /**
     * The order the delivery serves.
     */
    order_id: string;
    /**
     * The order's number.
     */
    order_number: string;
    /**
     * The stop's kind.
     */
    kind: TaskKind;
    /**
     * Where the task stands.
     */
    status: TaskStatus;
    /**
     * The stop.
     */
    heading_to: TaskStop;
};

/**
 * A change of a membership's status, with who made it, when and why.
 */
export type AgentStatusChange = {
    /**
     * The status after.
     */
    status: AgentMembershipStatus;
    /**
     * The status before; `null` for the first.
     */
    previous_status: AgentMembershipStatus | null;
    /**
     * Why.
     */
    reason: string | null;
    /**
     * Who; `null` for the platform itself.
     */
    by: string | null;
    /**
     * Their name.
     */
    by_name: string | null;
    /**
     * When.
     */
    at: string;
};

/**
 * How many Agents are in each status, and how many are online and busy now.
 */
export type AgentCounts = {
    /**
     * Invited.
     */
    invited: number;
    /**
     * Pending.
     */
    pending: number;
    /**
     * Active.
     */
    active: number;
    /**
     * Suspended.
     */
    suspended: number;
    /**
     * Offboarded.
     */
    offboarded: number;
    /**
     * Online now (busy included).
     */
    online: number;
    /**
     * Busy now.
     */
    busy: number;
};

/**
 * An Agent membership as the Partner's console and Mission Control read it: who, of what kind, where it stands and why, the documents it needs, its duty and presence, its current task and its cash in hand.
 */
export type PartnerAgent = {
    /**
     * The Agent membership.
     */
    id: string;
    /**
     * The Partner.
     */
    partner_id: string;
    /**
     * The Partner's name.
     */
    partner_name: string | null;
    /**
     * The delivery service.
     */
    service_id: string;
    /**
     * Its name.
     */
    service_name: string;
    /**
     * The Agent's name.
     */
    display_name: string;
    /**
     * What the Agent moves with.
     */
    kind: AgentKind;
    /**
     * Where the membership stands.
     */
    status: AgentMembershipStatus;
    /**
     * Why it is suspended or offboarded.
     */
    status_reason: string | null;
    /**
     * When the status last changed.
     */
    status_changed_at: string | null;
    /**
     * The person, once they joined.
     */
    user_id: string | null;
    /**
     * Their mobile number, E.164.
     */
    phone: string | null;
    /**
     * Their email.
     */
    email: string | null;
    /**
     * The invitation, while it is in progress.
     */
    invitation: AgentInvitationState | null;
    /**
     * When they accepted.
     */
    joined_at: string | null;
    /**
     * When the membership first became active.
     */
    activated_at: string | null;
    /**
     * Online (on duty and heard from within 60 seconds), busy (online with a task under way) or offline.
     */
    presence: AgentStatus;
    /**
     * Whether a duty stretch is open.
     */
    on_duty: boolean;
    /**
     * The zone the Agent works while on duty.
     */
    duty_zone: ZoneRef | null;
    /**
     * When the Agent's app was last heard from.
     */
    last_seen_at: string | null;
    /**
     * The last position, kept 6 hours, with when it was recorded on the device.
     */
    position: AgentPosition | null;
    /**
     * The task under way, the next stop first.
     */
    current_task: AgentTaskBrief | null;
    /**
     * Deliveries under way; a pickup and its drop count once.
     */
    tasks_under_way: number;
    /**
     * Cash collected and not yet settled.
     */
    cash_in_hand: Money;
    /**
     * The team; every Agent is in the service's default team.
     */
    team_id: string | null;
    /**
     * The documents the membership needs and where each stands.
     */
    documents: Array<AgentDocumentRequirement>;
    /**
     * What stops activation (while pending) or going on duty (while active); empty when nothing does.
     */
    blockers: Array<AgentBlocker>;
    /**
     * Arrivals recorded from outside a stop's geofence with a reason.
     */
    geofence_overrides: number;
    /**
     * Every change of status, newest first; read of one Agent only.
     */
    history?: Array<AgentStatusChange>;
    /**
     * When the membership (or its invitation) was made.
     */
    created_at: string;
    /**
     * When it last changed.
     */
    updated_at: string;
    /**
     * Raised by one on every change.
     */
    version: number;
};

/**
 * A page of Agents by name, with the counts of the whole selection.
 */
export type PartnerAgentPage = {
    /**
     * The Agents.
     */
    items: Array<PartnerAgent>;
    /**
     * The cursor of the next page; `null` on the last.
     */
    next_cursor: string | null;
    /**
     * How many in each status, and online and busy now, among those the filters select.
     */
    counts: AgentCounts;
};

/**
 * A duty stretch the platform closed because nothing was heard from the app for 30 minutes, told the next time the app opens.
 */
export type DutyClosure = {
    /**
     * The stretch.
     */
    stretch_id: string;
    /**
     * When it was closed: at the last report.
     */
    ended_at: string;
    /**
     * The zone it was in.
     */
    zone: ZoneRef | null;
};

/**
 * An Agent's duty: whether a stretch is open, in which zone, since when, and whether the Agent may go on duty now. Shifts are not required by any service yet, so every stretch is unscheduled.
 */
export type AgentDuty = {
    /**
     * The Agent membership.
     */
    agent_id: string;
    /**
     * Whether a duty stretch is open.
     */
    on_duty: boolean;
    /**
     * The open stretch.
     */
    stretch_id: string | null;
    /**
     * The zone chosen when going on duty.
     */
    zone: ZoneRef | null;
    /**
     * When the open stretch started.
     */
    started_at: string | null;
    /**
     * When the app was last heard from in this stretch.
     */
    last_heard_at: string | null;
    /**
     * Whether the stretch is outside any shift; always, until shifts arrive.
     */
    unscheduled: boolean;
    /**
     * Whether switching on would be accepted now.
     */
    can_go_on_duty: boolean;
    /**
     * Why the Agent cannot go on duty, in words.
     */
    blockers: Array<AgentBlocker>;
    /**
     * A stretch the platform closed for silence and has not told the Agent of yet; reading it here tells them.
     */
    closed_for_silence: DutyClosure | null;
};

/**
 * Switches duty on, in a zone, or off.
 */
export type AgentDutyUpdate = {
    /**
     * `true` to go on duty, `false` to go off.
     */
    on_duty: boolean;
    /**
     * The zone to work, required to go on duty: one `GET .../zones` offers.
     */
    zone_id?: string | null;
    /**
     * Where the Agent is, kept as the first position of the stretch.
     */
    position?: GeoPoint | null;
};

/**
 * A zone an Agent may choose when going on duty.
 */
export type DutyZone = {
    /**
     * The zone.
     */
    id: string;
    /**
     * Its name.
     */
    name: string;
    /**
     * Whether the position given lies in it; offered first.
     */
    here: boolean;
    /**
     * Whether it is in the service's area, where its deliveries are offered.
     */
    in_area: boolean;
};

/**
 * The zones an Agent may choose, the one they are in first, then the service's area, then the rest of the city by name.
 */
export type DutyZoneList = {
    /**
     * The zones.
     */
    items: Array<DutyZone>;
};

/**
 * One position from the Agent's device.
 */
export type AgentPositionReport = {
    /**
     * Latitude, -90 to 90.
     */
    lat: number;
    /**
     * Longitude, -180 to 180.
     */
    lng: number;
    /**
     * Direction of travel in degrees from true north, 0 to 360.
     */
    heading_deg?: number | null;
    /**
     * Speed in metres per second, at least 0.
     */
    speed_mps?: number | null;
    /**
     * The device's accuracy radius in metres, at least 0.
     */
    accuracy_m?: number | null;
    /**
     * When it was recorded on the device.
     */
    recorded_at: string;
};

/**
 * Positions recorded on the device, 1 to 500; an app back in signal sends what it kept in one batch. The newest one wins.
 */
export type AgentPositionBatch = {
    /**
     * The positions.
     */
    positions: Array<AgentPositionReport>;
};

/**
 * What became of a batch: applied while on duty, dropped and never kept otherwise.
 */
export type AgentPositionsAccepted = {
    /**
     * Positions applied.
     */
    accepted: number;
    /**
     * Positions dropped because the Agent is off duty.
     */
    dropped: number;
    /**
     * Whether the Agent is on duty; an app off duty stops reporting.
     */
    on_duty: boolean;
};

/**
 * One of the person's Agent memberships as the Agent app reads it: the service, where it stands and why, the documents still needed, duty, cash in hand and the pay rule in force.
 */
export type AgentMembership = {
    /**
     * The Agent membership.
     */
    id: string;
    /**
     * The Partner.
     */
    partner_id: string;
    /**
     * Its name.
     */
    partner_name: string;
    /**
     * The delivery service.
     */
    service_id: string;
    /**
     * Its name.
     */
    service_name: string;
    /**
     * The Agent's name.
     */
    display_name: string;
    /**
     * What the Agent moves with.
     */
    kind: AgentKind;
    /**
     * Where the membership stands.
     */
    status: AgentMembershipStatus;
    /**
     * Why it is suspended or offboarded, in the reviewer's words.
     */
    status_reason: string | null;
    /**
     * When the person accepted.
     */
    joined_at: string | null;
    /**
     * When it first became active.
     */
    activated_at: string | null;
    /**
     * Whether it is the membership the person works under now.
     */
    working: boolean;
    /**
     * The documents it needs and where each stands.
     */
    documents: Array<AgentDocumentRequirement>;
    /**
     * Duty, and whether the Agent may go on duty.
     */
    duty: AgentDuty;
    /**
     * Deliveries under way.
     */
    tasks_under_way: number;
    /**
     * Cash collected and not yet settled.
     */
    cash_in_hand: Money;
    /**
     * The service's cash ceiling, beyond which no task collecting cash is offered.
     */
    cash_ceiling: Money;
    /**
     * The version of the service's pay rule in force.
     */
    pay_rule_version: number;
};

/**
 * Every Agent membership of the person that is not offboarded, and the one they work under.
 */
export type AgentMembershipList = {
    /**
     * The memberships, the working one first.
     */
    items: Array<AgentMembership>;
    /**
     * The membership the person works under: the one on duty, else the one last chosen, else the first active one.
     */
    working_agent_id: string | null;
};

/**
 * The membership the person chooses to work under; the app shows only its tasks.
 */
export type AgentWorkingChoice = {
    /**
     * One of the person's memberships.
     */
    agent_id: string;
};

/**
 * An invitation in progress for the person's verified mobile number or email, as the Agent app lists it.
 */
export type AgentInvitation = {
    /**
     * The invitation.
     */
    id: string;
    /**
     * The Partner.
     */
    partner_id: string;
    /**
     * Its name.
     */
    partner_name: string;
    /**
     * The delivery service.
     */
    service_id: string;
    /**
     * Its name.
     */
    service_name: string;
    /**
     * The name the Partner invited them under.
     */
    display_name: string;
    /**
     * The kind they are invited as.
     */
    kind: AgentKind;
    /**
     * How they were told.
     */
    channel: AgentContactChannel;
    /**
     * When.
     */
    invited_at: string;
    /**
     * When it lapses.
     */
    expires_at: string;
};

/**
 * The invitations in progress for the person.
 */
export type AgentInvitationList = {
    /**
     * The invitations, newest first.
     */
    items: Array<AgentInvitation>;
};

/**
 * A line of the order the Agent carries.
 */
export type CarriedLine = {
    /**
     * What it is.
     */
    name: string;
    /**
     * How many.
     */
    quantity: number;
    /**
     * What was chosen in it.
     */
    choices: Array<string>;
};

/**
 * The customer of a task, as the platform's own Agents get them: the first name, the address and, for the task's duration, a number to call.
 */
export type TaskCustomer = {
    /**
     * Their first name.
     */
    first_name: string;
    /**
     * A number to call while the task is under way; `null` once it ends and to anyone but the Agent.
     */
    phone: string | null;
    /**
     * The drop address in words.
     */
    address: string | null;
    /**
     * The customer's note.
     */
    note: string | null;
};

/**
 * A step of a task's workflow and whether it is done.
 */
export type WorkflowStep = {
    /**
     * The step.
     */
    kind: TaskStepKind;
    /**
     * Whether the task cannot complete without it.
     */
    required: boolean;
    /**
     * Whether it is recorded.
     */
    done: boolean;
    /**
     * When it was recorded on the device.
     */
    done_at: string | null;
};

/**
 * A line of an Agent's pay.
 */
export type EarningLine = {
    /**
     * What it pays for.
     */
    kind: EarningLineKind;
    /**
     * The line in words.
     */
    label: string;
    /**
     * The amount.
     */
    amount: Money;
};

/**
 * The pay of a delivery under a version of the service's pay rule: an estimate at the planned routed distance when offered, earned at the measured distance on completion.
 */
export type PayQuote = {
    /**
     * The pay rule version it is under, kept for the task whatever is published later.
     */
    rule_version: number;
    /**
     * Each line of the breakdown.
     */
    lines: Array<EarningLine>;
    /**
     * The total.
     */
    total: Money;
};

/**
 * A task: one stop of a trip, with what the Agent carries, the customer while it is under way, the workflow's steps and the pay. The Agent app shows the trip's next stop first.
 */
export type AgentTask = {
    /**
     * The task.
     */
    id: string;
    /**
     * The trip bundling the delivery's pickup and drop.
     */
    trip_id: string;
    /**
     * The Agent membership holding it.
     */
    agent_id: string;
    /**
     * The Agent's Partner.
     */
    partner_id: string;
    /**
     * The delivery service.
     */
    service_id: string;
    /**
     * The delivery.
     */
    delivery_id: string;
    /**
     * The order.
     */
    order_id: string;
    /**
     * The order's number, as its label carries it.
     */
    order_number: string;
    /**
     * The stop's kind.
     */
    kind: TaskKind;
    /**
     * Its place in the trip, from 1.
     */
    sequence: number;
    /**
     * Where it stands.
     */
    status: TaskStatus;
    /**
     * How it reached the Agent.
     */
    assignment: TaskAssignment;
    /**
     * Where it takes the Agent.
     */
    stop: TaskStop;
    /**
     * What is carried.
     */
    lines: Array<CarriedLine>;
    /**
     * The customer; the number only while under way and only for the Agent.
     */
    customer: TaskCustomer | null;
    /**
     * Cash to collect at the drop.
     */
    cash_to_collect: Money | null;
    /**
     * The order's tip, the Agent's in full.
     */
    tip: Money | null;
    /**
     * Whether the drop asks for the customer's 4-digit code.
     */
    code_required: boolean;
    /**
     * Wrong codes left before the Agent is told to call the customer.
     */
    code_attempts_left: number | null;
    /**
     * The workflow's steps in order.
     */
    steps: Array<WorkflowStep>;
    /**
     * The reasons a drop may fail with.
     */
    failure_reasons: Array<string>;
    /**
     * The delivery's pay under its rule version.
     */
    pay: PayQuote;
    /**
     * When the Agent should be at the stop.
     */
    planned_at: string | null;
    /**
     * When the Agent was given it.
     */
    assigned_at: string;
    /**
     * When the Agent app received it.
     */
    received_at: string | null;
    /**
     * When the Agent started towards the stop.
     */
    started_at: string | null;
    /**
     * When the Agent arrived.
     */
    arrived_at: string | null;
    /**
     * When it completed, as recorded on the device.
     */
    completed_at: string | null;
    /**
     * When it ended without completing.
     */
    ended_at: string | null;
    /**
     * Why it failed, was called off, handed back or returned.
     */
    end_reason: string | null;
    /**
     * Until when a direct assignment may be handed back.
     */
    hand_back_until: string | null;
    /**
     * The reason given for arriving from outside the geofence.
     */
    arrive_override_reason: string | null;
    /**
     * The distance measured along the Agent's route for this stop.
     */
    measured_distance_m: number;
    /**
     * Raised by one on every change.
     */
    version: number;
    /**
     * Where the task sits in its trip, which may carry several deliveries; the app shows the trip's next stop first. Since 0.25.0.
     */
    trip?: AgentTaskTrip;
    /**
     * For a pickup, whether the store marked the order ready to collect; `null` for a drop. Since 0.25.0.
     */
    ready?: boolean | null;
};

/**
 * An Agent's tasks, the next stop first.
 */
export type AgentTaskList = {
    /**
     * The tasks.
     */
    items: Array<AgentTask>;
    /**
     * The next stop: the earliest task under way of the oldest trip.
     */
    next_task_id: string | null;
};

/**
 * A page of an Agent's tasks, newest first.
 */
export type AgentTaskPage = {
    /**
     * The tasks.
     */
    items: Array<AgentTask>;
    /**
     * The cursor of the next page; `null` on the last.
     */
    next_cursor: string | null;
};

/**
 * A step recorded in the Agent app, sent in order and applied once however often it is sent. Each carries a client id, when and where it was recorded, and what its kind needs: the scanned or typed `value` for a scan, the entered `value` for a code, an `asset_id` for a photo or a signature, the `amount` for cash, a `note`, a `reason` to fail, an `override_reason` to arrive from outside the geofence.
 */
export type TaskStepRecord = {
    /**
     * The app's id for this step; a repeat answers what the first did.
     */
    client_id: string;
    /**
     * The step.
     */
    kind: TaskStepKind;
    /**
     * When it was recorded on the device; a task completes at this time.
     */
    recorded_at: string;
    /**
     * Where it was recorded.
     */
    position?: GeoPoint | null;
    /**
     * For a scan, the order label's number; for a code, the 4 digits entered.
     */
    value?: string | null;
    /**
     * For a photo or a signature, the file posted with a proof upload grant.
     */
    asset_id?: string | null;
    /**
     * For cash, the amount collected.
     */
    amount?: Money | null;
    /**
     * For notes, at most 500 characters.
     */
    note?: string | null;
    /**
     * For fail, one of the task's failure reasons.
     */
    reason?: string | null;
    /**
     * For arrive from outside the geofence, why.
     */
    override_reason?: string | null;
};

/**
 * A step as the platform recorded it.
 */
export type TaskStepOutcome = {
    /**
     * The app's id for the step.
     */
    client_id: string;
    /**
     * The step.
     */
    kind: TaskStepKind;
    /**
     * When it was recorded on the device.
     */
    recorded_at: string;
    /**
     * When it reached the platform.
     */
    received_at: string;
    /**
     * Whether this answer is of a step sent before.
     */
    repeated: boolean;
};

/**
 * A step applied, with the task after it.
 */
export type TaskStepResult = {
    /**
     * The step.
     */
    step: TaskStepOutcome;
    /**
     * The task after the step.
     */
    task: AgentTask;
};

/**
 * Hands a direct assignment back within 60 seconds of receiving it.
 */
export type TaskHandBack = {
    /**
     * Why, 1 to 200 characters.
     */
    reason: string;
};

/**
 * Asks for help on a task in the Agent's words; the Partner's dispatcher and Mission Control see it on the delivery.
 */
export type TaskHelpRequest = {
    /**
     * What is wrong, 1 to 500 characters.
     */
    message: string;
};

/**
 * A request for help on a task.
 */
export type TaskHelp = {
    /**
     * The request.
     */
    id: string;
    /**
     * The task.
     */
    task_id: string;
    /**
     * The delivery.
     */
    delivery_id: string;
    /**
     * The order's number.
     */
    order_number: string;
    /**
     * The Agent's words.
     */
    message: string;
    /**
     * When.
     */
    requested_at: string;
};

/**
 * A piece of proof kept on a task with when and where it was recorded. A photo or a signature is a private file (purpose `proof_of_delivery_photo`) read through its ten-minute link; the code is kept as matched, never as the digits.
 */
export type ProofItem = {
    /**
     * What it is.
     */
    kind: ProofKind;
    /**
     * The file, for a photo or a signature.
     */
    asset_id: string | null;
    /**
     * The number scanned or typed, for a scan.
     */
    scanned: string | null;
    /**
     * Whether a scan matched the order's number or a code the customer's code; `true` for files.
     */
    matched: boolean;
    /**
     * When it was recorded on the device.
     */
    recorded_at: string;
    /**
     * Where.
     */
    position: GeoPoint | null;
    /**
     * A link to the file, minted for this read and recorded.
     */
    link: SignedLink | null;
};

/**
 * The proof kept on a delivery's drop: what was recorded at the door, readable by the customer of the order, the Partner and Mission Control for 365 days, never deleted or replaced after the task completed.
 */
export type ProofOfDelivery = {
    /**
     * The order.
     */
    order_id: string;
    /**
     * Its number.
     */
    order_number: string;
    /**
     * The delivery.
     */
    delivery_id: string;
    /**
     * The drop task.
     */
    task_id: string;
    /**
     * Where the drop stands.
     */
    status: TaskStatus;
    /**
     * When the drop completed, as recorded on the device.
     */
    delivered_at: string | null;
    /**
     * The Agent's first name.
     */
    agent_first_name: string;
    /**
     * The proof, in the order it was recorded.
     */
    items: Array<ProofItem>;
    /**
     * Until when it is kept.
     */
    keep_until: string;
};

/**
 * What a task earned, with its breakdown under the rule version it was offered under.
 */
export type TaskEarning = {
    /**
     * The task.
     */
    task_id: string;
    /**
     * The delivery.
     */
    delivery_id: string;
    /**
     * The order's number.
     */
    order_number: string;
    /**
     * The stop's kind.
     */
    kind: TaskKind;
    /**
     * Why it paid.
     */
    outcome: EarningOutcome;
    /**
     * The pay rule version.
     */
    rule_version: number;
    /**
     * The breakdown.
     */
    lines: Array<EarningLine>;
    /**
     * The total, tip included.
     */
    total: Money;
    /**
     * When it was earned: the step's recorded time.
     */
    earned_at: string;
};

/**
 * An Agent's day on the India calendar: each task's pay with its breakdown, the tips, the total and the cash in hand now.
 */
export type AgentDay = {
    /**
     * The Agent membership.
     */
    agent_id: string;
    /**
     * The day.
     */
    date: string;
    /**
     * The calendar the day is read on.
     */
    time_zone: string;
    /**
     * Each task that earned, in order.
     */
    tasks: Array<TaskEarning>;
    /**
     * Drops completed.
     */
    deliveries: number;
    /**
     * Tips, in full.
     */
    tips: Money;
    /**
     * Everything earned, tips included.
     */
    total: Money;
    /**
     * Cash collected and not yet settled, now.
     */
    cash_in_hand: Money;
};

/**
 * Cash an Agent collected at a drop.
 */
export type CashCollection = {
    /**
     * The task.
     */
    task_id: string;
    /**
     * The order's number.
     */
    order_number: string;
    /**
     * What was collected.
     */
    amount: Money;
    /**
     * When.
     */
    collected_at: string;
};

/**
 * Cash an Agent holds: collected at drops and not yet settled with the Partner, against the service's ceiling.
 */
export type CashInHand = {
    /**
     * The Agent membership.
     */
    agent_id: string;
    /**
     * Cash in hand.
     */
    amount: Money;
    /**
     * The service's cash ceiling.
     */
    ceiling: Money;
    /**
     * The collections not yet settled, newest first.
     */
    collections: Array<CashCollection>;
};

/**
 * A published version of a delivery service's pay rule: a base per pickup and per drop-off, an amount per kilometre of routed distance between stops, waiting pay per minute beyond the free minutes at a pickup, what a task called off after the Agent started towards it pays, and tips in full. A task keeps the version it was offered under.
 */
export type PayRule = {
    /**
     * The version.
     */
    id: string;
    /**
     * The Partner.
     */
    partner_id: string;
    /**
     * The delivery service.
     */
    service_id: string;
    /**
     * The version, from 1.
     */
    version: number;
    /**
     * Per pickup.
     */
    pickup: Money;
    /**
     * Per drop-off.
     */
    drop_off: Money;
    /**
     * Per kilometre of routed distance between stops.
     */
    per_km: Money;
    /**
     * Per minute of waiting beyond the free minutes at a pickup.
     */
    waiting_per_minute: Money;
    /**
     * Minutes of waiting at a pickup that pay nothing.
     */
    waiting_free_minutes: number;
    /**
     * What a task called off after the Agent started towards it pays.
     */
    call_off: Money;
    /**
     * What changed, for the Agents.
     */
    note: string | null;
    /**
     * When it was published.
     */
    published_at: string;
    /**
     * Who published it; `null` for the defaults.
     */
    published_by: string | null;
};

/**
 * Every published version of a service's pay rule, newest first.
 */
export type PayRuleList = {
    /**
     * The versions.
     */
    items: Array<PayRule>;
    /**
     * The version in force for new offers.
     */
    current_version: number;
};

/**
 * A new version of the pay rule, in force for offers made after it. Amounts in the service's currency, 0 or more.
 */
export type PayRulePublish = {
    /**
     * Per pickup.
     */
    pickup: Money;
    /**
     * Per drop-off.
     */
    drop_off: Money;
    /**
     * Per kilometre.
     */
    per_km: Money;
    /**
     * Per minute of waiting beyond the free minutes.
     */
    waiting_per_minute: Money;
    /**
     * Free minutes at a pickup, 0 to 60.
     */
    waiting_free_minutes: number;
    /**
     * For a task called off after the Agent started towards it.
     */
    call_off: Money;
    /**
     * What changed, at most 200 characters.
     */
    note?: string | null;
};

/**
 * A team of a delivery service's Agents with the area dispatch offers its deliveries in. Every service has one default team holding every Agent, whose area is the zones the service delivers in, else the zones of its Locations; teams beyond the default come later.
 */
export type AgentTeam = {
    /**
     * The team.
     */
    id: string;
    /**
     * The Partner.
     */
    partner_id: string;
    /**
     * The delivery service.
     */
    service_id: string;
    /**
     * Its name.
     */
    name: string;
    /**
     * Whether it is the default team.
     */
    default: boolean;
    /**
     * The kinds it is limited to; empty for every kind.
     */
    kinds: Array<AgentKind>;
    /**
     * Its area.
     */
    zones: Array<ZoneRef>;
    /**
     * Where the area comes from.
     */
    area_source: TeamAreaSource;
    /**
     * Agents in it, offboarded ones left out.
     */
    agent_count: number;
};

/**
 * A service's teams.
 */
export type AgentTeamList = {
    /**
     * The teams, the default first.
     */
    items: Array<AgentTeam>;
};

/**
 * A step of a workflow template.
 */
export type WorkflowTemplateStep = {
    /**
     * The step.
     */
    kind: TaskStepKind;
    /**
     * Whether a task cannot complete without it.
     */
    required: boolean;
};

/**
 * The steps of a kind of stop for a service, the platform's defaults as the service's settings adjust them: a pickup is navigate, arrive, scan and notes; a drop-off navigate, arrive, photo and notes, with a signature and the customer's code when the service asks for them, and cash when the order collects it.
 */
export type WorkflowTemplate = {
    /**
     * The kind of stop.
     */
    kind: TaskKind;
    /**
     * The steps in order.
     */
    steps: Array<WorkflowTemplateStep>;
    /**
     * The reasons a stop of this kind may fail with.
     */
    failure_reasons: Array<string>;
};

/**
 * How a delivery service runs its Agents' work: the geofence of arrival, whether a drop asks for the customer's code or a signature, whether police verification is required, the cash ceiling, the limit of deliveries under way (from the service's delivery configuration) and the workflow templates.
 */
export type AgentServiceSettings = {
    /**
     * The delivery service.
     */
    service_id: string;
    /**
     * The Partner.
     */
    partner_id: string;
    /**
     * How near a stop an Agent must be to arrive without an override, 50 to 500.
     */
    geofence_metres: number;
    /**
     * Whether a drop asks for the customer's 4-digit code.
     */
    drop_code_required: boolean;
    /**
     * Whether a drop asks for a signature.
     */
    signature_required: boolean;
    /**
     * Whether the membership needs police verification.
     */
    police_verification_required: boolean;
    /**
     * Cash in hand beyond which no task collecting cash is offered.
     */
    cash_ceiling: Money;
    /**
     * Deliveries an Agent carries at once, the service's `max_concurrent_tasks`.
     */
    task_limit: number;
    /**
     * The workflow of each kind of stop.
     */
    templates: Array<WorkflowTemplate>;
    /**
     * Raised by one on every change; 1 while the defaults stand.
     */
    version: number;
    /**
     * When last changed.
     */
    updated_at: string | null;
    /**
     * Who last changed it.
     */
    updated_by: string | null;
};

/**
 * Changes a service's settings; absent members are kept.
 */
export type AgentServiceSettingsUpdate = {
    /**
     * 50 to 500.
     */
    geofence_metres?: number | null;
    /**
     * Whether a drop asks for the customer's code.
     */
    drop_code_required?: boolean | null;
    /**
     * Whether a drop asks for a signature.
     */
    signature_required?: boolean | null;
    /**
     * Whether police verification is required.
     */
    police_verification_required?: boolean | null;
    /**
     * The cash ceiling, 0 or more, in the service's currency.
     */
    cash_ceiling?: Money | null;
    /**
     * The reasons a drop may fail with, 1 to 12 of 1 to 80 characters.
     */
    failure_reasons?: Array<string> | null;
};

/**
 * A document the membership needs, with where it stands.
 */
export type AgentDocumentRequirement = {
    /**
     * The document.
     */
    kind: AgentDocumentKind;
    /**
     * Whether the membership needs it to become active.
     */
    required: boolean;
    /**
     * Why it is needed, in words.
     */
    reason: string;
    /**
     * Where the latest document of this kind stands; `null` when none is filed.
     */
    status: AgentDocumentStatus | null;
    /**
     * The latest document of this kind.
     */
    document_id: string | null;
    /**
     * When it expires, for a licence and a registration.
     */
    expires_on: string | null;
    /**
     * Whether it is approved and not expired.
     */
    satisfied: boolean;
};

/**
 * An event as published by ZippyGo: the envelope defined by the event
 * schemas in this repository (`events/envelope.schema.json`), with the
 * business data in `payload`. The shape of `payload` is defined per `type`
 * and `version` in the event catalog.
 *
 */
export type Event = {
    /**
     * Unique identifier of the event, a UUID version 7 so that ids sort by creation time. Deduplicate on it.
     */
    id: string;
    /**
     * The event type as `<domain>.<event>`, for example `fleet.agent.online`. The full list is in the event catalog.
     */
    type: string;
    /**
     * The payload schema version for this event type.
     */
    version: number;
    /**
     * When the event happened, as an RFC 3339 timestamp in UTC.
     */
    occurred_at: string;
    /**
     * The partner the event belongs to, or `null` for platform-level events that are not scoped to a partner.
     */
    partner_id: string | null;
    /**
     * Shared by every event and request that stem from the same originating action, or `null` when the event was not caused by a traceable request.
     */
    correlation_id: string | null;
    /**
     * The event data, as defined by `type` and `version` in the event catalog.
     */
    payload: {
        [key: string]: unknown;
    };
};

/**
 * A list of events, the response of `GET /v1/events`.
 */
export type EventList = {
    /**
     * The events, newest first.
     */
    items: Array<Event>;
};

/**
 * How the customer is reached, per channel, the `CustomerNotificationPreferences`
 * schema. Messages about an order, a payment, a refund or the account always
 * send, whatever the marketing consent says; marketing goes only by the
 * channels the customer agreed to. Push reaches every device signed in and
 * registered; a customer with none is told by WhatsApp when they opted in to
 * order updates there, else by SMS; email goes where an email is on file.
 *
 */
export type CustomerNotificationPreferences = {
    /**
     * Whether the customer opted in to order updates on WhatsApp. WhatsApp is never used without it.
     */
    whatsapp_updates: boolean;
    /**
     * When the customer opted in; `null` while they have not.
     */
    whatsapp_opted_in_at: string | null;
    /**
     * Whether the SMS provider reported the number on the national do-not-disturb register. Marketing SMS stops; order messages still arrive.
     */
    sms_do_not_disturb: boolean;
    /**
     * When the provider first reported it.
     */
    sms_do_not_disturb_since: string | null;
    /**
     * Whether the profile holds an email, where receipts and other email rows go.
     */
    email_on_file: boolean;
    /**
     * How many of the customer's signed-in devices are registered for pushes.
     */
    push_devices: number;
    marketing: MarketingConsent;
    /**
     * Whether the customer is shown recommendations: often ordered with, nearby complements and reorder prompts, which also need the push marketing consent. On by default; off stops every one of them at once, while messages about an order, and the ask to review it, still come.
     */
    recommendations: boolean;
    /**
     * Raised by one on every change; the entity tag of reads.
     */
    version: number;
};

/**
 * Changes how the customer is reached, the request of `PUT /v1/customer/notification-preferences`; a member left out stays as it is. Marketing consent is its own act (`PUT /v1/customer/consent`).
 */
export type CustomerNotificationPreferencesUpdate = {
    /**
     * Opt in to order updates on WhatsApp, or out of them.
     */
    whatsapp_updates?: boolean;
    /**
     * Turn recommendations and reorder prompts on, or off at once.
     */
    recommendations?: boolean;
};

/**
 * One message of the delivery log, the `DeliveryLogEntry` schema: what it
 * told, by which channel, to whom, with which template version, and what
 * became of it. Times are when it was queued, sent and, where the provider
 * reports it, delivered or read. The composed words are kept 30 days and the
 * entry 90.
 *
 */
export type DeliveryLogEntry = {
    /**
     * The message.
     */
    id: string;
    /**
     * What it tells of, the event type it was composed from (`ordering.order.accepted`), or `notifications.notice.sent`, or `notifications.message.resent`.
     */
    event: string;
    /**
     * The event it was composed from, when one.
     */
    event_id: string | null;
    /**
     * The template it was composed with, by name.
     */
    template: string;
    /**
     * The version of the template; a message keeps the version it was composed with.
     */
    template_version: number;
    /**
     * The language it was composed in (`en`, `te`, `hi`).
     */
    language: string;
    channel: NotificationChannel;
    /**
     * `true` for messages about an order, a payment, a refund, a notice or the account, which send whatever the marketing consent says.
     */
    transactional: boolean;
    recipient: MessageRecipient;
    /**
     * The order it is about, when one.
     */
    order_id: string | null;
    /**
     * The Location it is about, when one.
     */
    location_id: string | null;
    /**
     * The Partner it is about, when one.
     */
    partner_id: string | null;
    /**
     * The Agent it is about, when one (Agents are told from a later step).
     */
    agent_id: string | null;
    status: MessageStatus;
    /**
     * Why it was skipped or failed, with the provider's own words when the provider refused it.
     */
    reason: string | null;
    /**
     * How many times the sender tried it.
     */
    attempts: number;
    /**
     * The provider it went through (`local`, `smtp`, `msg91`, `fcm`).
     */
    provider: string | null;
    /**
     * The provider's reference for the send, where it gives one.
     */
    provider_ref: string | null;
    /**
     * For a push, every device it went to and what became of each; empty otherwise.
     */
    devices: Array<MessageDevice>;
    /**
     * When it was queued, with the change it tells of.
     */
    queued_at: string;
    /**
     * The earliest moment it may be sent.
     */
    not_before: string;
    /**
     * When the provider accepted it.
     */
    sent_at: string | null;
    /**
     * When it was delivered, where the channel reports it (the local stand-ins deliver at once).
     */
    delivered_at: string | null;
    /**
     * When it was first read or opened, where the channel reports it.
     */
    read_at: string | null;
    /**
     * When it was given up.
     */
    failed_at: string | null;
    /**
     * The words it was composed with; `null` after 30 days.
     */
    text: MessageText | null;
    /**
     * The message it resends, for a resend from Mission Control.
     */
    resend_of: string | null;
};

/**
 * A page of the delivery log, the response of `GET /v1/platform/messages`.
 */
export type DeliveryLogPage = {
    /**
     * The messages on this page, newest first unless sorted otherwise.
     */
    items: Array<DeliveryLogEntry>;
    /**
     * An opaque cursor to pass as `cursor` for the next page, or `null` when this is the last page.
     */
    next_cursor: string | null;
    /**
     * Facet counts, present when `facets` was asked for (`channel`, `status`, `recipient_kind`).
     */
    facets?: Array<Facet>;
};

/**
 * A notice in a Location's inbox, shared by everybody who signs in to the Location.
 */
export type InboxNotice = {
    /**
     * The notice.
     */
    notice_id: string;
    /**
     * Its title.
     */
    title: string;
    /**
     * Its message.
     */
    message: string;
    /**
     * When it was sent.
     */
    sent_at: string;
    /**
     * When it leaves the inbox by itself, seven days after sending.
     */
    expires_at: string;
    /**
     * When somebody at the Location first saw it; `null` while it is unread.
     */
    first_seen_at: string | null;
};

/**
 * One device a push went to and what the provider made of it.
 */
export type MessageDevice = {
    /**
     * The device identity the session named, else the registration.
     */
    device: string;
    platform: PushPlatform;
    /**
     * `sent`, `unregistered` (the provider says the registration is gone; it was dropped), `failed` (refused) or `pending` (to be tried again).
     */
    outcome: 'sent' | 'unregistered' | 'failed' | 'pending';
    /**
     * The provider's reference for the send, where it gives one.
     */
    provider_ref: string | null;
};

/**
 * Who a message is for, with the number or address masked to its last characters.
 */
export type MessageRecipient = {
    kind: RecipientKind;
    /**
     * The customer, for a customer's message; the Agent's person once they accepted, for an Agent's.
     */
    user_id: string | null;
    /**
     * The Location, for a Location's devices or one of its contacts.
     */
    location_id: string | null;
    /**
     * The address masked to its last characters (`…3210`, `a…@example.com`) or the devices it went to.
     */
    label: string;
};

/**
 * Where a message is: `queued` waiting for its moment or its turn, `sending` claimed by the sender, `sent` accepted by the channel's provider, `skipped` not sent on purpose (no credentials in this environment, a reserved address, no live device, an order answered before its reminder), `failed` refused by the provider or still undeliverable after the retries at 1, 5 and 30 minutes. Clients must tolerate values they do not know.
 */
export type MessageStatus = 'queued' | 'sending' | 'sent' | 'skipped' | 'failed';

/**
 * The words a message was composed with, kept 30 days; nothing of a prescription is ever composed into a message.
 */
export type MessageText = {
    /**
     * The email subject or the push title; `null` for SMS and WhatsApp.
     */
    subject: string | null;
    /**
     * The text as the recipient reads it.
     */
    body: string;
};

/**
 * One notice as sent, the `Notice` schema: who sent it, when, its words, the
 * Locations named and how many it reached, and how many have seen and
 * cleared it. A notice cannot be recalled. Each Location keeps it seven days
 * from sending, whether or not anybody clears it.
 *
 */
export type Notice = {
    /**
     * The notice.
     */
    id: string;
    /**
     * Its title.
     */
    title: string;
    /**
     * Its message.
     */
    message: string;
    /**
     * The template its words started from, when one.
     */
    template_id: string | null;
    /**
     * The platform member who sent it.
     */
    sent_by: string;
    /**
     * Their name at the time.
     */
    sent_by_label: string | null;
    /**
     * When it was sent.
     */
    sent_at: string;
    /**
     * When it leaves every inbox, seven days after sending.
     */
    expires_at: string;
    /**
     * How many Locations the request named.
     */
    locations_named: number;
    /**
     * How many it was stored for; archived and unknown ones are not counted.
     */
    locations_reached: number;
    /**
     * How many of those have seen it.
     */
    seen: number;
    /**
     * How many of those have cleared it.
     */
    cleared: number;
};

/**
 * The notices to clear from the inbox, the request of `POST .../notices/clear`. Name them in `notice_ids`, or send `all` true to clear the whole inbox; one of the two is required (`selection_required`). Only the Location's own notices are cleared.
 */
export type NoticeClear = {
    /**
     * The notices to clear.
     */
    notice_ids?: Array<string>;
    /**
     * Clear every notice of the inbox.
     */
    all?: boolean;
};

/**
 * One Location's copy of a notice, as the send log keeps it.
 */
export type NoticeDelivery = {
    /**
     * The Location.
     */
    location_id: string;
    /**
     * Its Partner.
     */
    partner_id: string;
    /**
     * When it was stored in the Location's inbox, before anybody was told.
     */
    stored_at: string;
    /**
     * When somebody at the Location first saw it; `null` while not yet seen.
     */
    first_seen_at: string | null;
    /**
     * When the Location cleared it from its inbox.
     */
    cleared_at: string | null;
};

/**
 * A notice with every Location it reached, seen or not yet seen, the response of `GET /v1/platform/notices/{notice_id}`.
 */
export type NoticeDetail = {
    notice: Notice;
    /**
     * Every Location it was stored for.
     */
    deliveries: Array<NoticeDelivery>;
};

/**
 * A page of a Location's inbox, the response of `GET /v1/partners/{partner_id}/locations/{location_id}/notices`, with how many are unread and how many the page is not showing.
 */
export type NoticeInbox = {
    /**
     * The notices on this page, newest first, or oldest first with `order=oldest`.
     */
    items: Array<InboxNotice>;
    /**
     * An opaque cursor to pass as `cursor` for the next page, or `null` when this is the last page.
     */
    next_cursor: string | null;
    /**
     * How many notices the inbox holds now (the filter applied).
     */
    total: number;
    /**
     * How many of the inbox's notices nobody has seen yet.
     */
    unread: number;
    /**
     * How many notices matching the request this page does not show.
     */
    not_shown: number;
};

/**
 * A page of notices sent, newest first, the response of `GET /v1/platform/notices`.
 */
export type NoticeList = {
    /**
     * The notices on this page.
     */
    items: Array<Notice>;
    /**
     * An opaque cursor to pass as `cursor` for the next page, or `null` when this is the last page.
     */
    next_cursor: string | null;
};

/**
 * Where a Location's screen presents a notice: `prominent` (over the screen) or `corner` (a corner of it).
 */
export type NoticePlacement = 'prominent' | 'corner';

/**
 * How a Location's screen presents a notice, the `NoticePresentation`
 * schema: where it appears, and whether it waits to be acknowledged or
 * clears itself after a short while showing the time remaining. Platform
 * configuration, set in Mission Control, not a preference the Location sets
 * for itself. A Location configured with nothing reads as prominent and
 * waiting. A notice that clears itself stays unread in the inbox until
 * somebody reads it there.
 *
 */
export type NoticePresentation = {
    placement: NoticePlacement;
    /**
     * Whether a notice stays until acknowledged; `false` clears it after a short while.
     */
    waits: boolean;
    /**
     * `false` while nothing was set and the defaults apply.
     */
    configured: boolean;
    /**
     * Raised by one on every change, `0` while never set; the entity tag of reads.
     */
    version: number;
    /**
     * When it was last set.
     */
    updated_at: string | null;
};

/**
 * Sets how a Location's screen presents a notice, the request of `PUT .../notice-presentation`.
 */
export type NoticePresentationInput = {
    placement: NoticePlacement;
    /**
     * Whether a notice stays until acknowledged.
     */
    waits: boolean;
};

/**
 * The notices to mark seen, the request of `POST .../notices/seen`; without `notice_ids` every notice of the inbox is marked. Only the Location's own notices are touched, and a notice already seen keeps its first sighting.
 */
export type NoticeSelection = {
    /**
     * The notices to mark; absent for all of them.
     */
    notice_ids?: Array<string>;
};

/**
 * A notice to send, the request of `POST /v1/platform/notices`. It carries
 * its own words, never a template to resolve later, and names Locations,
 * never a group: a group is a way of choosing Locations, resolved by the
 * console before the request. A blank title or message, whitespace only
 * included, is refused (`blank_text`).
 *
 */
export type NoticeSend = {
    /**
     * The title each Location reads.
     */
    title: string;
    /**
     * The message each Location reads.
     */
    message: string;
    /**
     * The Locations to send it to. One archived since it was chosen, or unknown, is skipped, not counted and not an error.
     */
    location_ids: Array<string>;
    /**
     * The template the words started from, kept for the record only.
     */
    template_id?: string | null;
};

/**
 * What sending a notice did, the response of `POST /v1/platform/notices`.
 */
export type NoticeSent = {
    notice: Notice;
    /**
     * The Locations named that were skipped, with why.
     */
    skipped: Array<NoticeSkip>;
};

/**
 * A Location a notice was not sent to, and why.
 */
export type NoticeSkip = {
    /**
     * The Location named.
     */
    location_id: string;
    /**
     * `archived` (archived since it was chosen) or `unknown` (no such Location).
     */
    reason: 'archived' | 'unknown';
};

/**
 * A starting point for a notice, kept by name in Mission Control, the
 * `NoticeTemplate` schema. Choosing one fills a notice's title and message,
 * which stay editable; the notice carries its own words, so changing a
 * template never changes what a Location was told. A template is withdrawn
 * from the send picker (`offered: false`) rather than deleted.
 *
 */
export type NoticeTemplate = {
    /**
     * The template.
     */
    id: string;
    /**
     * Its name, unique without regard to case.
     */
    name: string;
    /**
     * The title a notice starts from.
     */
    title: string;
    /**
     * The message a notice starts from.
     */
    message: string;
    /**
     * Whether the send picker offers it; a template not offered keeps its words and can be offered again.
     */
    offered: boolean;
    /**
     * Raised by one on every change; the entity tag of reads.
     */
    version: number;
    /**
     * When it was written.
     */
    created_at: string;
    /**
     * When it last changed.
     */
    updated_at: string;
};

/**
 * A new notice template, the request of `POST /v1/platform/notice-templates`. A name that differs from another only in case is refused (`409`, `notice_template_name_taken`); a blank name, title or message is refused (`blank_text`).
 */
export type NoticeTemplateInput = {
    /**
     * Its name.
     */
    name: string;
    /**
     * The title a notice starts from.
     */
    title: string;
    /**
     * The message a notice starts from.
     */
    message: string;
    /**
     * Whether the send picker offers it.
     */
    offered?: boolean;
};

/**
 * Notice templates by name, the response of `GET /v1/platform/notice-templates`.
 */
export type NoticeTemplateList = {
    /**
     * The templates, by name.
     */
    items: Array<NoticeTemplate>;
};

/**
 * Changes a notice template, the request of `PATCH /v1/platform/notice-templates/{template_id}`; members left out keep their value. Withdraw a template with `offered` false.
 */
export type NoticeTemplateUpdate = {
    /**
     * Its new name.
     */
    name?: string;
    /**
     * Its new title.
     */
    title?: string;
    /**
     * Its new message.
     */
    message?: string;
    /**
     * Whether the send picker offers it.
     */
    offered?: boolean;
};

/**
 * How many notices were cleared; `0` when none of those named is in the Location's inbox.
 */
export type NoticesCleared = {
    /**
     * The notices cleared by this request.
     */
    cleared: number;
};

/**
 * How many notices were marked seen now; `0` when every one named had been seen already, or none of them is the Location's.
 */
export type NoticesMarked = {
    /**
     * The notices marked seen by this request.
     */
    marked: number;
};

/**
 * The channel a message leaves by: `push` to the Customer, Partner and Agent apps and the web consoles, `sms` under a registered DLT template, `whatsapp` through an approved Business template to a customer who opted in, `email`. A Location's notices have an inbox of their own. Clients must tolerate values they do not know.
 */
export type NotificationChannel = 'push' | 'sms' | 'whatsapp' | 'email';

/**
 * Tells the platform a push was opened on this device, the request of `POST /v1/me/push/opened`; the delivery log records the first opening as the message's `read_at`.
 */
export type PushOpened = {
    /**
     * The `message_id` the push carried in its data.
     */
    message_id: string;
};

/**
 * What kind of device a push registration is for: `android` and `ios` for the apps, `web` for a browser (the Storefront and the consoles). Every platform receives pushes through Firebase Cloud Messaging; clients must tolerate values they do not know.
 */
export type PushPlatform = 'android' | 'ios' | 'web';

/**
 * The push registration of the calling session's device, the `PushRegistration` schema.
 */
export type PushRegistration = {
    /**
     * The registration.
     */
    id: string;
    audience: Audience;
    platform: PushPlatform;
    /**
     * The device identity the session was opened with, when the client named one; pushes filed by the local stand-in are addressed to it.
     */
    device_id: string | null;
    /**
     * The Location a Partner device is set to; `null` for every other surface and for a member's device that follows every Location they reach.
     */
    location_id: string | null;
    /**
     * When the device first registered in this session.
     */
    created_at: string;
    /**
     * When the registration last changed (a new token, another Location).
     */
    updated_at: string;
};

/**
 * Registers the device of the calling session for pushes, the request of
 * `PUT /v1/me/push`. The registration belongs to the session: signing the
 * device out, ending the session or its expiry stops its pushes. A token
 * another session registered moves to this one.
 *
 */
export type PushRegistrationInput = {
    /**
     * The push token the device's messaging library gave it (a Firebase Cloud Messaging registration token).
     */
    token: string;
    platform: PushPlatform;
    /**
     * On a Partner token only: the Location the console or app is set to, so the device is pushed about that Location alone. Absent or `null`, a member's device is pushed about every Location their grants cover. Refused on other surfaces, and `404` for a Location the member does not reach.
     */
    location_id?: string | null;
};

/**
 * Who a message is for: `customer` (a customer's devices, number or email), `location` (every device signed in to a Location, resolved when the message is sent), `contact` (a person a Location lists as a contact, by the channel they agreed to) or `agent` (the person of an Agent membership: their Agent app devices, number or email, the invited one before they accept).
 */
export type RecipientKind = 'customer' | 'location' | 'contact' | 'agent';

/**
 * A stream of server-sent events, as defined by the WHATWG HTML standard,
 * with the media type `text/event-stream`. Each frame is an `event:` line
 * naming the event type, a `data:` line carrying JSON (empty for
 * `heartbeat`) and a blank line. The event types and the shape of their
 * data are documented on each streaming operation. OpenAPI has no native
 * type for a stream, so the body is modelled as a string.
 *
 */
export type ServerSentEventStream = string;

/**
 * The data of a `snapshot` frame on `GET /v1/live/agents`, sent once when the stream opens. It holds every agent that matches the stream's filters, with its current status and position.
 */
export type AgentSnapshot = {
    /**
     * The agents at the time the stream opened.
     */
    agents: Array<Agent>;
};

/**
 * The data of a `position` frame on `GET /v1/live/agents`, sent when an agent's position changes.
 */
export type AgentPositionUpdate = {
    /**
     * The agent that moved.
     */
    agent_id: string;
    /**
     * The agent's new position.
     */
    position: AgentPosition;
    /**
     * The agent's status at the time of the update.
     */
    status: AgentStatus;
    /**
     * The service the agent works in; absent when unknown.
     */
    service_id?: string | null;
    /**
     * The service's name; absent when unknown.
     */
    service_name?: string | null;
};

/**
 * The data of a `status` frame on `GET /v1/live/agents`, sent when an agent goes online, busy or offline, and when its task changes.
 */
