    /**
     * The code it came through.
     */
    code: string | null;
    /**
     * Reserved, confirmed or released.
     */
    status: RedemptionStatus;
    /**
     * What it took off.
     */
    saving: Money;
    /**
     * The Partner's share.
     */
    partner_cost: Money;
    /**
     * The platform's share.
     */
    platform_cost: Money;
    /**
     * When it was reserved.
     */
